#!/usr/bin/env node
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
loadChangmenEnv();
const { ensurePgPoolReady } = await import("@changmen/db");
const pool = await ensurePgPoolReady();

const { rows } = await pool.query(`
  WITH dup AS (
    SELECT o.user_id, o.provider, o.order_id, COUNT(*)::int AS rows
    FROM orders o
    GROUP BY o.user_id, o.provider, o.order_id
    HAVING COUNT(*) > 1
  ),
  user_agg AS (
    SELECT user_id,
           COUNT(*)::int AS dup_groups,
           SUM(rows - 1)::int AS extra_rows,
           SUM(rows)::int AS total_dup_rows
    FROM dup
    GROUP BY user_id
  ),
  provider_agg AS (
    SELECT user_id, provider, COUNT(*)::int AS n
    FROM dup
    GROUP BY user_id, provider
  )
  SELECT u.user_name,
         ua.user_id,
         ua.dup_groups,
         ua.extra_rows,
         ua.total_dup_rows,
         (SELECT jsonb_object_agg(provider, n ORDER BY provider)
          FROM provider_agg pa WHERE pa.user_id = ua.user_id) AS by_provider
  FROM user_agg ua
  JOIN users u ON u.id = ua.user_id
  ORDER BY ua.dup_groups DESC, u.user_name
`);

console.log(`全库有重复 order_id 的用户: ${rows.length}\n`);

if (!rows.length) {
  console.log("（无）");
}
else {
  console.log("user\t重复组\t多余副本\t组内总行\t按平台");
  for (const r of rows) {
    const prov = r.by_provider && typeof r.by_provider === "object"
      ? Object.entries(r.by_provider).map(([k, v]) => `${k}:${v}`).join(", ")
      : "-";
    console.log(`${r.user_name}\t${r.dup_groups}\t${r.extra_rows}\t${r.total_dup_rows}\t${prov}`);
  }
}

const totals = await pool.query(`
  SELECT COUNT(*)::int AS dup_groups,
         COALESCE(SUM(cnt - 1), 0)::int AS extra_rows
  FROM (
    SELECT COUNT(*)::int AS cnt
    FROM orders
    GROUP BY user_id, provider, order_id
    HAVING COUNT(*) > 1
  ) t
`);
console.log(`\n全库合计: ${totals.rows[0].dup_groups} 重复组, ${totals.rows[0].extra_rows} 条多余副本`);

await pool.end();

#!/usr/bin/env node
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady, getPgPool } from "@changmen/db";

loadChangmenEnv();
await ensurePgPoolReady();
const pool = getPgPool();
if (!pool) {
  console.error("NO_POOL");
  process.exit(1);
}

const { rows: users } = await pool.query(
  `SELECT id, user_name FROM users WHERE user_name ILIKE $1`,
  ["%GB12%"],
);
console.log("users:", users);

for (const u of users) {
  const { rows: sellCnt } = await pool.query(
    `SELECT COUNT(*)::int AS n FROM orders
     WHERE user_id = $1 AND provider = 'Polymarket' AND raw->>'pmSide' = 'sell'`,
    [u.id],
  );
  const { rows: sells } = await pool.query(
    `SELECT id, order_id, player_id, item, raw->>'pmSide' AS pm_side, create_at
     FROM orders
     WHERE user_id = $1 AND provider = 'Polymarket' AND raw->>'pmSide' = 'sell'
     ORDER BY create_at DESC`,
    [u.id],
  );
  console.log(`user ${u.user_name}: sell count = ${sellCnt[0]?.n}`);
  for (const s of sells)
    console.log(`  id=${s.id} player=${s.player_id} order_id=${s.order_id} item=${s.item}`);
}

const { rows: prof } = await pool.query(
  `SELECT p.id, p.user_name, a.elem
   FROM profiles p,
   LATERAL jsonb_array_elements(COALESCE(p.accounts, '[]'::jsonb)) AS a(elem)
   WHERE a.elem->>'playerName' ILIKE $1
      OR a.elem->>'userName' ILIKE $1
      OR p.user_name ILIKE $1`,
  ["%GB12%"],
);
console.log("account matches:", prof.length);
for (const p of prof) {
  const playerId = Number(p.elem?.accountId);
  if (!Number.isFinite(playerId) || playerId <= 0)
    continue;
  const { rows: sells } = await pool.query(
    `SELECT id, order_id, player_id, item, raw->>'pmSide' AS pm_side, create_at
     FROM orders
     WHERE player_id = $1 AND provider = 'Polymarket' AND raw->>'pmSide' = 'sell'`,
    [playerId],
  );
  console.log(`player ${playerId} (${p.elem?.playerName}): ${sells.length} sells`);
  for (const s of sells)
    console.log(`  id=${s.id} order_id=${s.order_id} item=${s.item}`);
}

// 平仓 item 但 pmSide 缺失的兜底
const { rows: ambiguous } = await pool.query(
  `SELECT o.id, o.order_id, o.player_id, o.item, o.raw->>'pmSide' AS pm_side, p.user_name
   FROM orders o
   LEFT JOIN profiles p ON p.id = o.user_id
   WHERE o.provider = 'Polymarket'
     AND (o.item LIKE '平仓%' OR o.item LIKE '平仓 %')
     AND COALESCE(o.raw->>'pmSide', '') != 'buy'
   ORDER BY o.create_at DESC
   LIMIT 20`,
);
console.log("ambiguous 平仓 rows (pmSide != buy):", ambiguous.length);
for (const a of ambiguous)
  console.log(`  id=${a.id} user=${a.user_name} player=${a.player_id} pm_side=${a.pm_side} item=${a.item}`);

await pool.end();

#!/usr/bin/env node
/** 检查跨用户是否共用同一场馆操盘账号（venue_member_id / gateway+token） */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
loadChangmenEnv();
const { ensurePgPoolReady } = await import("@changmen/db");
const pool = await ensurePgPoolReady();

const byVenueMember = await pool.query(`
  SELECT pl.provider, pl.venue_member_id,
         COUNT(DISTINCT pl.owner_user_id)::int AS users,
         array_agg(DISTINCT u.user_name ORDER BY u.user_name) AS user_names,
         array_agg(pl.id ORDER BY pl.id) AS player_ids
  FROM players pl
  JOIN users u ON u.id = pl.owner_user_id
  WHERE pl.deleted_at IS NULL
    AND pl.venue_member_id <> ''
    AND pl.provider <> ''
  GROUP BY pl.provider, pl.venue_member_id
  HAVING COUNT(DISTINCT pl.owner_user_id) > 1
  ORDER BY users DESC, pl.provider
  LIMIT 30
`);

console.log("=== 跨用户共用 venue_member_id ===");
console.log(`组数: ${byVenueMember.rows.length}`);
for (const r of byVenueMember.rows) {
  console.log(`${r.provider}\t${r.venue_member_id}\tusers=${r.user_names.join(",")}\tpids=${r.player_ids.join(",")}`);
}

const byGatewayToken = await pool.query(`
  SELECT pl.provider,
         pl.account_data->>'gateway' AS gateway,
         md5(COALESCE(pl.account_data->>'token', '')) AS token_hash,
         COUNT(DISTINCT pl.owner_user_id)::int AS users,
         array_agg(DISTINCT u.user_name ORDER BY u.user_name) AS user_names
  FROM players pl
  JOIN users u ON u.id = pl.owner_user_id
  WHERE pl.deleted_at IS NULL
    AND COALESCE(pl.account_data->>'gateway', '') <> ''
    AND COALESCE(pl.account_data->>'token', '') <> ''
  GROUP BY pl.provider, pl.account_data->>'gateway', md5(COALESCE(pl.account_data->>'token', ''))
  HAVING COUNT(DISTINCT pl.owner_user_id) > 1
  ORDER BY users DESC
  LIMIT 20
`);

console.log("\n=== 跨用户相同 gateway+token ===");
console.log(`组数: ${byGatewayToken.rows.length}`);
for (const r of byGatewayToken.rows) {
  console.log(`${r.provider}\t${r.user_names.join(",")}\tgateway=${String(r.gateway).slice(0, 40)} token_hash=${r.token_hash.slice(0, 12)}…`);
}

await pool.end();

