#!/usr/bin/env node
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
loadChangmenEnv();
const { ensurePgPoolReady } = await import("@changmen/db");
const pool = await ensurePgPoolReady();

const userName = process.argv.find(a => a.startsWith("--user="))?.slice(7) || "GB14";
const { rows: users } = await pool.query(
  `SELECT id, user_name FROM users WHERE user_name ILIKE $1 LIMIT 1`,
  [userName],
);
const uid = users[0]?.id;
if (!uid) {
  console.error(`用户 ${userName} 不存在`);
  process.exit(1);
}

const dupGroups = await pool.query(
  `SELECT o.provider, o.order_id,
          COUNT(*)::int AS rows,
          COUNT(DISTINCT o.player_id)::int AS players,
          array_agg(o.player_id ORDER BY o.player_id) AS player_ids,
          array_agg(pl.platform_name ORDER BY o.player_id) AS platforms,
          array_agg(pl.player_name ORDER BY o.player_id) AS names,
          array_agg(pl.deleted_at IS NOT NULL ORDER BY o.player_id) AS soft_flags
   FROM orders o
   JOIN players pl ON pl.id = o.player_id
   WHERE o.user_id = $1::uuid
   GROUP BY o.provider, o.order_id
   HAVING COUNT(*) > 1
   ORDER BY o.provider, o.order_id`,
  [uid],
);

let activeActive = 0;
let softActive = 0;
let softSoft = 0;
let totalExtraRows = 0;

for (const g of dupGroups.rows) {
  const soft = g.soft_flags;
  const hasActive = soft.some(s => !s);
  const hasSoft = soft.some(s => s);
  totalExtraRows += g.rows - 1;
  if (hasActive && soft.every(s => !s))
    activeActive += 1;
  else if (hasActive && hasSoft)
    softActive += 1;
  else if (hasSoft && !hasActive)
    softSoft += 1;
}

const activeCount = await pool.query(
  `SELECT COUNT(*)::int AS n FROM players WHERE owner_user_id = $1::uuid AND deleted_at IS NULL`,
  [uid],
);
const softCount = await pool.query(
  `SELECT COUNT(*)::int AS n FROM players WHERE owner_user_id = $1::uuid AND deleted_at IS NOT NULL`,
  [uid],
);
const softWithOrders = await pool.query(
  `SELECT pl.id, pl.platform_name, pl.player_name, COUNT(o.id)::int AS n
   FROM players pl
   JOIN orders o ON o.player_id = pl.id AND o.user_id = $1::uuid
   WHERE pl.owner_user_id = $1::uuid AND pl.deleted_at IS NOT NULL
   GROUP BY pl.id, pl.platform_name, pl.player_name
   ORDER BY n DESC, pl.id`,
  [uid],
);

console.log(`user=${users[0].user_name} (${uid})`);
console.log(`活跃 player: ${activeCount.rows[0].n}  软删 player: ${softCount.rows[0].n}`);
console.log(`重复 order_id 组: ${dupGroups.rows.length}`);
console.log(`多余行(可删副本): ${totalExtraRows}`);
console.log(`  活跃↔活跃: ${activeActive}`);
console.log(`  软删↔活跃: ${softActive}`);
console.log(`  软删↔软删: ${softSoft}`);

const byProvider = {};
for (const g of dupGroups.rows) {
  byProvider[g.provider] = (byProvider[g.provider] ?? 0) + 1;
}
if (Object.keys(byProvider).length)
  console.log("按平台:", byProvider);

if (dupGroups.rows.length) {
  console.log("\n明细:");
  for (const g of dupGroups.rows) {
    const tags = g.player_ids.map((id, i) =>
      `${id}${g.soft_flags[i] ? "S" : "A"}(${g.platforms[i]}/${g.names[i]})`,
    ).join(" vs ");
    console.log(`${g.provider}\t${g.order_id}\t${tags}`);
  }
}

if (softWithOrders.rows.length) {
  console.log("\n软删仍有订单:");
  for (const r of softWithOrders.rows)
    console.log(`  ${r.id}\t${r.platform_name}/${r.player_name}\t${r.n} 条`);
}

await pool.end();

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 订单栏相关 RDS 只读全面巡检（不写库）
 *
 *   node scripts/ops/diagnostics/audit-order-sidebar-health.mjs
 *   node scripts/ops/diagnostics/audit-order-sidebar-health.mjs --user gb14
 *   node scripts/ops/diagnostics/audit-order-sidebar-health.mjs --days 14
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

function parseArgs(argv) {
  const out = { userName: "", days: 30, limit: 30, help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--days")
      out.days = Math.max(1, Number(argv[++i]) || 30);
    else if (a === "--limit")
      out.limit = Math.max(5, Number(argv[++i]) || 30);
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function num(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function shTime(ms) {
  const t = Number(ms) || 0;
  if (!t)
    return "";
  return new Date(t).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false });
}

function shortId(id) {
  const s = String(id ?? "");
  return s.length > 14 ? `${s.slice(0, 10)}…` : s;
}

function near(a, b, tol = 2) {
  return Math.abs(a - b) <= tol;
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/diagnostics/audit-order-sidebar-health.mjs [--user NAME] [--days N] [--limit N]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();
  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  const profiles = await fetchProfiles();
  const nameById = new Map();
  for (const p of profiles) {
    const id = String(p.id ?? p.user_id ?? "");
    nameById.set(id, String(p.user_name ?? p.userName ?? id).trim());
  }

  let userIds = null;
  if (args.userName) {
    const want = args.userName.toLowerCase();
    userIds = profiles
      .filter(p => String(p.user_name ?? p.userName ?? "").toLowerCase() === want)
      .map(p => String(p.id ?? p.user_id ?? ""));
    if (!userIds.length) {
      console.error(`user not found: ${args.userName}`);
      process.exit(1);
    }
  }

  const sinceMs = Date.now() - args.days * 24 * 3600 * 1000;
  const params = [sinceMs];
  const filters = ["create_at >= $1"];
  if (userIds) {
    params.push(userIds);
    filters.push(`user_id = ANY($${params.length}::text[])`);
  }

  const { rows } = await pool.query(`
    SELECT order_id, user_id, player_id, provider, link, match, bet, item,
           money, bet_money, status, create_at, raw
    FROM ${financialOrdersRelation()}
    WHERE ${filters.join(" AND ")}
    ORDER BY create_at DESC
  `, params);

  const fx = getExchange(Currency.USDT);
  const byId = new Map();
  const pmBuys = [];
  const pmSells = [];
  const pfBuys = [];
  const pfSells = [];
  const other = [];

  for (const r of rows) {
    byId.set(String(r.order_id).trim().toLowerCase(), r);
    const prov = String(r.provider ?? "").trim().toLowerCase();
    const raw = rawObj(r);
    const side = String(raw.pmSide ?? raw.pfSide ?? "").toLowerCase();
    if (prov === "polymarket") {
      if (side === "sell")
        pmSells.push(r);
      else
        pmBuys.push(r);
    }
    else if (prov === "predictfun") {
      if (side === "sell" || String(raw.pfSide ?? "").toLowerCase() === "sell")
        pfSells.push(r);
      else
        pfBuys.push(r);
    }
    else {
      other.push(r);
    }
  }

  const sellsByBuy = new Map();
  for (const s of pmSells) {
    const buyId = String(rawObj(s).pmBuyOrderId ?? "").trim().toLowerCase();
    if (!buyId)
      continue;
    if (!sellsByBuy.has(buyId))
      sellsByBuy.set(buyId, []);
    sellsByBuy.get(buyId).push(s);
  }

  const pfSellsByBuy = new Map();
  for (const s of pfSells) {
    const buyId = String(rawObj(s).pfBuyOrderId ?? rawObj(s).pmBuyOrderId ?? "").trim().toLowerCase();
    if (!buyId)
      continue;
    if (!pfSellsByBuy.has(buyId))
      pfSellsByBuy.set(buyId, []);
    pfSellsByBuy.get(buyId).push(s);
  }

  const buckets = {
    pm_money_2x_sell_pnl: [],
    pm_buy_and_sell_both_money: [],
    pm_closed_money_mismatch: [],
    pm_attr_full_but_state_open: [],
    pm_sold_out_but_stake_left: [],
    pm_orphan_sell_no_buy: [],
    pm_sell_link_mismatch: [],
    pm_sell_missing_buy_id: [],
    pf_buy_and_sell_both_money: [],
    pf_closed_money_mismatch: [],
    pf_orphan_sell: [],
    pf_money_looks_already_cny: [],
    link_placeholder_only: [],
    status_win_lose_but_pm_manual_sold: [],
  };

  function sample(item) {
    return {
      user: nameById.get(String(item.user_id)) || item.user_id,
      playerId: item.player_id,
      orderId: shortId(item.order_id),
      match: item.match,
      item: item.item,
      money: num(item.money),
      betMoney: num(item.bet_money),
      status: item.status,
      link: item.link,
      createAtShanghai: shTime(item.create_at),
      ...item._extra,
    };
  }

  function push(bucket, row, extra = {}) {
    buckets[bucket].push(sample({ ...row, _extra: extra }));
  }

  // --- PM buys ---
  for (const buy of pmBuys) {
    const raw = rawObj(buy);
    const id = String(buy.order_id).trim().toLowerCase();
    const sells = sellsByBuy.get(id) || [];
    const state = String(raw.pmSellState ?? "").toLowerCase();
    const fill = num(raw.pmShares);
    const attr = num(raw.pmAttributedSellShares);
    const rem = Math.max(0, Math.round((fill - attr) * 10000) / 10000);
    const remEff = rem <= 0.01 ? 0 : rem;
    const stake = num(raw.pmStakeUsdc);
    const buyMoney = num(buy.money);
    const sellMoneySum = sells.reduce((s, x) => s + num(x.money), 0);

    let expected = 0;
    let hasPnl = false;
    for (const s of sells) {
      const pnl = num(rawObj(s).pmRealizedPnlUsdc);
      if (Math.abs(pnl) > 1e-9) {
        hasPnl = true;
        expected += Math.round(pnl * fx);
      }
    }
    if (!hasPnl) {
      for (const s of sells) {
        const proceeds = num(s.bet_money);
        const cost = num(rawObj(s).pmStakeUsdc);
        if (proceeds > 0 && cost > 0)
          expected += Math.round(proceeds - cost * fx);
      }
    }

    if (sells.length && Math.abs(expected) >= 5 && near(Math.abs(buyMoney), Math.abs(expected) * 2) && !near(Math.abs(buyMoney), Math.abs(expected)))
      push("pm_money_2x_sell_pnl", buy, { expected, sellCount: sells.length, state });

    if (sells.length && Math.abs(buyMoney) > 1 && Math.abs(sellMoneySum) > 1)
      push("pm_buy_and_sell_both_money", buy, { sellMoneySum, expected, state });

    if ((state === "closed" || state === "partial") && sells.length && Math.abs(expected) >= 5) {
      if (!near(Math.abs(buyMoney), Math.abs(expected), 3) && !near(Math.abs(buyMoney), Math.abs(expected) * 2, 3))
        push("pm_closed_money_mismatch", buy, { expected, state, sellCount: sells.length, delta: Math.round(buyMoney - expected) });
    }

    if (attr > 0.01 && state === "open")
      push("pm_attr_full_but_state_open", buy, { fill, attr, remEff, stake });

    if (remEff === 0 && (attr > 0 || sells.length) && stake > 0.05)
      push("pm_sold_out_but_stake_left", buy, { fill, attr, stake, state });

    const st = String(buy.status ?? "").toLowerCase();
    if ((st === "win" || st === "lose") && (state === "closed" || state === "partial") && sells.length)
      push("status_win_lose_but_pm_manual_sold", buy, { status: buy.status, state });
  }

  // --- PM sells ---
  for (const sell of pmSells) {
    const raw = rawObj(sell);
    const buyId = String(raw.pmBuyOrderId ?? "").trim().toLowerCase();
    if (!buyId) {
      push("pm_sell_missing_buy_id", sell, { origin: raw.pmOrigin });
      continue;
    }
    const buy = byId.get(buyId);
    if (!buy)
      push("pm_orphan_sell_no_buy", sell, { buyId: shortId(buyId), origin: raw.pmOrigin });
    else if (String(sell.link ?? "") !== String(buy.link ?? "") && Number(sell.link) && Number(buy.link))
      push("pm_sell_link_mismatch", sell, {
        sellLink: sell.link,
        buyLink: buy.link,
        buyId: shortId(buyId),
      });
  }

  // --- PF ---
  for (const buy of pfBuys) {
    const raw = rawObj(buy);
    const id = String(buy.order_id).trim().toLowerCase();
    const sells = pfSellsByBuy.get(id) || [];
    const state = String(raw.pfSellState ?? "").toLowerCase();
    const buyMoney = num(buy.money);
    const sellMoneySum = sells.reduce((s, x) => s + num(x.money), 0);
    const bet = num(buy.bet_money);

    // 库内应为 USDT；若 money 很大且像已×6.7（相对 bet），标可疑
    if (Math.abs(buyMoney) > 50 && Math.abs(bet) > 0 && Math.abs(buyMoney / bet) > 4)
      push("pf_money_looks_already_cny", buy, { ratio: Math.round((buyMoney / bet) * 100) / 100, state });

    if (sells.length && Math.abs(buyMoney) > 0.01 && Math.abs(sellMoneySum) > 0.01)
      push("pf_buy_and_sell_both_money", buy, { sellMoneySum, state });

    if (state === "closed" && sells.length) {
      const proceeds = sells.reduce((s, x) => s + num(x.bet_money), 0);
      const expected = Math.round((proceeds - bet) * 100) / 100;
      if (Math.abs(expected) >= 0.5 && !near(buyMoney, expected, 0.5) && !near(buyMoney, expected * fx, 2))
        push("pf_closed_money_mismatch", buy, { expectedUsdt: expected, buyMoney, state });
    }
  }

  for (const sell of pfSells) {
    const raw = rawObj(sell);
    const buyId = String(raw.pfBuyOrderId ?? raw.pmBuyOrderId ?? "").trim().toLowerCase();
    if (!buyId || !byId.get(buyId))
      push("pf_orphan_sell", sell, { buyId: shortId(buyId || "(missing)") });
  }

  // placeholder-only groups: link==create_at and no peers? skip heavy; count links with single reject?
  const summary = {
    scannedAtShanghai: new Date().toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false }),
    windowDays: args.days,
    sinceShanghai: shTime(sinceMs),
    fx,
    totals: {
      orders: rows.length,
      pmBuys: pmBuys.length,
      pmSells: pmSells.length,
      pfBuys: pfBuys.length,
      pfSells: pfSells.length,
      other: other.length,
    },
    issueCounts: {},
    issues: {},
  };

  for (const [k, list] of Object.entries(buckets)) {
    summary.issueCounts[k] = list.length;
    summary.issues[k] = list.slice(0, args.limit);
  }

  const severity = {
    critical: ["pm_money_2x_sell_pnl", "pm_buy_and_sell_both_money"],
    high: [
      "pm_closed_money_mismatch",
      "pm_attr_full_but_state_open",
      "pm_sold_out_but_stake_left",
      "pm_orphan_sell_no_buy",
      "pf_buy_and_sell_both_money",
      "pf_closed_money_mismatch",
    ],
    medium: [
      "pm_sell_link_mismatch",
      "pm_sell_missing_buy_id",
      "pf_orphan_sell",
      "pf_money_looks_already_cny",
      "status_win_lose_but_pm_manual_sold",
    ],
  };

  const scored = { critical: 0, high: 0, medium: 0 };
  for (const [sev, keys] of Object.entries(severity)) {
    for (const k of keys)
      scored[sev] += summary.issueCounts[k] || 0;
  }
  summary.severityTotals = scored;

  console.log(JSON.stringify(summary, null, 2));
  await pool.end?.();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * Phase 0 — 仓位双写覆盖率只读巡检（不写库）
 *
 * 度量：
 * - PM/PF 独立卖单行数量
 * - 仓位（买单）含 positionEvents.sells 的数量
 * - 卖单 id 已在父仓位事件中 / 缺失
 * - 仓位有减仓状态但无事件、或有事件但无对应卖单行
 *
 *   node scripts/ops/diagnostics/audit-position-dual-write.mjs
 *   node scripts/ops/diagnostics/audit-position-dual-write.mjs --days 30
 *   node scripts/ops/diagnostics/audit-position-dual-write.mjs --user GB13 --limit 20
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

function parseArgs(argv) {
  const out = { userName: "", days: 30, limit: 20, help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--days")
      out.days = Math.max(1, Number(argv[++i]) || 30);
    else if (a === "--limit")
      out.limit = Math.max(5, Number(argv[++i]) || 20);
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
}

function sideOf(row) {
  const raw = rawObj(row);
  const p = String(row.provider || "").trim();
  if (p === "Polymarket")
    return String(raw.pmSide || "").toLowerCase() === "sell" ? "sell" : "buy";
  if (p === "PredictFun")
    return String(raw.pfSide || "").toLowerCase() === "sell" ? "sell" : "buy";
  return "";
}

function parentBuyId(row) {
  const raw = rawObj(row);
  const p = String(row.provider || "").trim();
  if (p === "Polymarket")
    return String(raw.pmBuyOrderId || "").trim().toLowerCase();
  if (p === "PredictFun")
    return String(raw.pfBuyOrderId || "").trim().toLowerCase();
  return "";
}

function eventIds(row) {
  const raw = rawObj(row);
  const pe = raw.positionEvents && typeof raw.positionEvents === "object" ? raw.positionEvents : {};
  const sells = Array.isArray(pe.sells) ? pe.sells : (Array.isArray(raw.sells) ? raw.sells : []);
  const ids = new Set();
  for (const ev of sells) {
    const id = String(ev?.id ?? ev?.orderId ?? "").trim().toLowerCase();
    if (id)
      ids.add(id);
  }
  return ids;
}

function sellState(row) {
  const raw = rawObj(row);
  const p = String(row.provider || "").trim();
  if (p === "Polymarket")
    return String(raw.pmSellState || "").toLowerCase();
  if (p === "PredictFun")
    return String(raw.pfSellState || "").toLowerCase();
  return "";
}

function shortId(id) {
  const s = String(id ?? "");
  return s.length > 18 ? `${s.slice(0, 12)}…` : s;
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/diagnostics/audit-position-dual-write.mjs [--user NAME] [--days N] [--limit N]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();
  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  const profiles = await fetchProfiles();
  const nameById = new Map();
  let filterUserId = null;
  for (const p of profiles) {
    const id = String(p.id ?? p.user_id ?? "");
    const name = String(p.user_name ?? p.userName ?? id).trim();
    nameById.set(id, name);
    if (args.userName && name.toLowerCase() === args.userName.toLowerCase())
      filterUserId = id;
  }
  if (args.userName && !filterUserId) {
    console.error(`user not found: ${args.userName}`);
    process.exit(1);
  }

  const since = Date.now() - args.days * 86400_000;
  const params = [since];
  let userClause = "";
  if (filterUserId) {
    params.push(filterUserId);
    userClause = ` AND user_id = $${params.length}::uuid`;
  }

  const { rows } = await pool.query(
    `SELECT id, user_id, player_id, order_id, provider, money, bet_money, create_at, raw
     FROM ${financialOrdersRelation()}
     WHERE create_at >= $1
       AND provider IN ('Polymarket', 'PredictFun')
       ${userClause}
     ORDER BY create_at DESC`,
    params,
  );

  const buys = [];
  const sells = [];
  for (const row of rows) {
    const side = sideOf(row);
    if (side === "sell")
      sells.push(row);
    else if (side === "buy")
      buys.push(row);
  }

  const buyByKey = new Map();
  for (const b of buys) {
    const key = `${b.user_id}|${String(b.order_id).trim().toLowerCase()}`;
    buyByKey.set(key, b);
  }

  let sellsWithParent = 0;
  let sellsParentMissing = 0;
  let sellsEventPresent = 0;
  let sellsEventMissing = 0;
  const eventMissingSamples = [];
  const parentMissingSamples = [];

  for (const s of sells) {
    const buyId = parentBuyId(s);
    if (!buyId) {
      sellsParentMissing += 1;
      if (parentMissingSamples.length < args.limit) {
        parentMissingSamples.push({
          user: nameById.get(String(s.user_id)) || s.user_id,
          provider: s.provider,
          sellId: shortId(s.order_id),
          reason: "no_buy_id",
        });
      }
      continue;
    }
    sellsWithParent += 1;
    const parent = buyByKey.get(`${s.user_id}|${buyId}`);
    if (!parent) {
      // 父仓位可能在窗口外：再查一次全库该 order_id（只读）
      const { rows: found } = await pool.query(
        `SELECT order_id, raw FROM ${financialOrdersRelation()}
         WHERE user_id = $1::uuid AND provider = $2
           AND lower(order_id) = $3
         LIMIT 1`,
        [s.user_id, s.provider, buyId],
      );
      if (!found[0]) {
        sellsParentMissing += 1;
        if (parentMissingSamples.length < args.limit) {
          parentMissingSamples.push({
            user: nameById.get(String(s.user_id)) || s.user_id,
            provider: s.provider,
            sellId: shortId(s.order_id),
            buyId: shortId(buyId),
            reason: "buy_row_absent",
          });
        }
        continue;
      }
      const ids = eventIds(found[0]);
      if (ids.has(String(s.order_id).trim().toLowerCase()))
        sellsEventPresent += 1;
      else {
        sellsEventMissing += 1;
        if (eventMissingSamples.length < args.limit) {
          eventMissingSamples.push({
            user: nameById.get(String(s.user_id)) || s.user_id,
            provider: s.provider,
            sellId: shortId(s.order_id),
            buyId: shortId(buyId),
          });
        }
      }
      continue;
    }
    const ids = eventIds(parent);
    if (ids.has(String(s.order_id).trim().toLowerCase()))
      sellsEventPresent += 1;
    else {
      sellsEventMissing += 1;
      if (eventMissingSamples.length < args.limit) {
        eventMissingSamples.push({
          user: nameById.get(String(s.user_id)) || s.user_id,
          provider: s.provider,
          sellId: shortId(s.order_id),
          buyId: shortId(buyId),
        });
      }
    }
  }

  let buysWithEvents = 0;
  let buysReducedNoEvents = 0;
  let buysMarketSettled = 0;
  let buysEventsNoSellRows = 0;
  const reducedNoEventSamples = [];
  const eventsNoSellSamples = [];

  const sellIdsByUser = new Map();
  for (const s of sells) {
    const uid = String(s.user_id);
    if (!sellIdsByUser.has(uid))
      sellIdsByUser.set(uid, new Set());
    sellIdsByUser.get(uid).add(String(s.order_id).trim().toLowerCase());
  }

  for (const b of buys) {
    const ids = eventIds(b);
    if (ids.size > 0)
      buysWithEvents += 1;
    const st = sellState(b);
    // partial/closed/closing = 手动减仓；settled = 赛果结算（非卖出流水，不应要求 positionEvents.sells）
    const manuallyReduced = st === "partial" || st === "closed" || st === "closing";
    if (st === "settled")
      buysMarketSettled += 1;
    if (manuallyReduced && ids.size === 0) {
      buysReducedNoEvents += 1;
      if (reducedNoEventSamples.length < args.limit) {
        reducedNoEventSamples.push({
          user: nameById.get(String(b.user_id)) || b.user_id,
          provider: b.provider,
          buyId: shortId(b.order_id),
          sellState: st || "(empty)",
        });
      }
    }
    if (ids.size > 0) {
      const knownSells = sellIdsByUser.get(String(b.user_id)) || new Set();
      let orphanEvents = 0;
      for (const id of ids) {
        if (!knownSells.has(id))
          orphanEvents += 1;
      }
      // 窗口内无对应卖单行的事件（可能卖单在窗口外或已单写）
      if (orphanEvents === ids.size) {
        buysEventsNoSellRows += 1;
        if (eventsNoSellSamples.length < args.limit) {
          eventsNoSellSamples.push({
            user: nameById.get(String(b.user_id)) || b.user_id,
            provider: b.provider,
            buyId: shortId(b.order_id),
            eventCount: ids.size,
          });
        }
      }
    }
  }

  const byProv = { Polymarket: { buy: 0, sell: 0 }, PredictFun: { buy: 0, sell: 0 } };
  for (const b of buys) {
    if (byProv[b.provider])
      byProv[b.provider].buy += 1;
  }
  for (const s of sells) {
    if (byProv[s.provider])
      byProv[s.provider].sell += 1;
  }

  console.log(`== audit-position-dual-write days=${args.days}${args.userName ? ` user=${args.userName}` : ""} ==`);
  console.log(`rows_in_window: ${rows.length}  buys: ${buys.length}  sells: ${sells.length}`);
  console.table([
    { provider: "Polymarket", buys: byProv.Polymarket.buy, sells: byProv.Polymarket.sell },
    { provider: "PredictFun", buys: byProv.PredictFun.buy, sells: byProv.PredictFun.sell },
  ]);
  console.log("\n-- sell rows vs parent events --");
  console.log(JSON.stringify({
    sells_total: sells.length,
    sells_with_parent_id: sellsWithParent,
    sells_parent_missing: sellsParentMissing,
    sells_event_present_on_buy: sellsEventPresent,
    sells_event_missing_on_buy: sellsEventMissing,
    coverage_pct: sells.length
      ? Math.round((1000 * sellsEventPresent) / Math.max(1, sellsWithParent || sells.length)) / 10
      : 100,
  }, null, 2));
  console.log("\n-- buy (position) health --");
  console.log(JSON.stringify({
    buys_total: buys.length,
    buys_with_position_events: buysWithEvents,
    buys_manually_reduced_but_no_events: buysReducedNoEvents,
    buys_market_settled: buysMarketSettled,
    buys_events_without_window_sell_rows: buysEventsNoSellRows,
  }, null, 2));

  if (eventMissingSamples.length) {
    console.log("\n-- samples: sell row missing on parent positionEvents --");
    console.table(eventMissingSamples);
  }
  if (parentMissingSamples.length) {
    console.log("\n-- samples: sell without resolvable parent buy --");
    console.table(parentMissingSamples);
  }
  if (reducedNoEventSamples.length) {
    console.log("\n-- samples: reduced position but no events --");
    console.table(reducedNoEventSamples);
  }
  if (eventsNoSellSamples.length) {
    console.log("\n-- samples: position events with no sell rows in window --");
    console.table(eventsNoSellSamples);
  }

  console.log("\nOK  read-only baseline complete (no writes)");
  await pool.end();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * 诊断 client_match 是否在 Web 可见
 *   cd changmen/server/backend && node scripts/check-client-match.mjs 161
 */

import { ensurePgPoolReady, getResolvedDatabaseLabel } from "@changmen/db";

const matchId = Number(process.argv[2] || 161);
if (!Number.isFinite(matchId)) {
  console.error("用法: node scripts/check-client-match.mjs <client_match_id>");
  process.exit(1);
}

const pool = await ensurePgPoolReady();
if (!pool) {
  console.error("无法连接 RDS：请检查 backend/.env 中的 DATABASE_URL");
  process.exit(1);
}

const label = getResolvedDatabaseLabel() || "connected";
console.log(`[check] client_match #${matchId} · DB=${label}\n`);

const cm = await pool.query(
  `SELECT id, title, game, start_time, bo, round, built_at, matchs, bets
   FROM client_matches WHERE id = $1`,
  [matchId],
);

if (!cm.rows.length) {
  console.log(`❌ client_matches 中不存在 id=${matchId}`);
  console.log("   → Web 不可见：活跃表只保存当前可见比赛，过期/隐藏行会进入 client_matches_history\n");
  const hist = await pool.query(
    `SELECT id, title, game, start_time, bo, round, built_at, archived_at, matchs, bets
     FROM client_matches_history WHERE id = $1
     ORDER BY archived_at DESC NULLS LAST
     LIMIT 1`,
    [matchId],
  );
  if (hist.rows.length) {
    const h = hist.rows[0];
    console.log("── client_matches_history ──");
    console.log("  title:       ", h.title);
    console.log("  archived_at: ", h.archived_at);
    console.log("  built_at:    ", h.built_at ? new Date(Number(h.built_at)).toISOString() : "(无)");
    console.log("  matchs:      ", JSON.stringify(h.matchs));
  }
}
else {
  const row = cm.rows[0];
  const platforms = Object.keys(row.matchs || {});
  const betCount = Array.isArray(row.bets) ? row.bets.length : 0;
  const startMs = Number(row.start_time) || 0;
  const startIso = startMs ? new Date(startMs < 1e12 ? startMs * 1000 : startMs).toISOString() : "(无)";

  console.log("── client_matches ──");
  console.log("  title:       ", row.title);
  console.log("  game:        ", row.game);
  console.log("  start_time:  ", startIso);
  console.log("  built_at:    ", row.built_at ? new Date(Number(row.built_at)).toISOString() : "(无)");
  console.log("  platforms:   ", platforms.join(", ") || "(空)", `(${platforms.length})`);
  console.log("  bets:        ", betCount, "条");
  console.log("  matchs:      ", JSON.stringify(row.matchs));
  console.log("\n✅ Web 应可见（存在于 client_matches 活跃表）");
  if (platforms.length < 2) {
    console.log("⚠️  平台数 < 2：下次 matchMerge 可能被 filterMultiPlatform 滤掉并删除");
  }
}

const pm = await pool.query(
  `SELECT platform, source_match_id, match_id, home, away, start_time, synced_at
   FROM platform_matches
   WHERE match_id = $1
      OR (platform = 'RAY' AND source_match_id = '38398938')
      OR (platform = 'IA' AND source_match_id = '373860')
   ORDER BY platform`,
  [matchId],
);

console.log("\n── platform_matches（RAY/IA 关联行）──");
if (!pm.rows.length) {
  console.log("  (无匹配行)");
}
else {
  const now = Date.now();
  for (const r of pm.rows) {
    const syncedRaw = r.synced_at;
    const syncedMs = syncedRaw != null ? Number(syncedRaw) : Number.NaN;
    const synced
      = Number.isFinite(syncedMs) && syncedMs > 0
        ? new Date(syncedMs < 1e12 ? syncedMs * 1000 : syncedMs).toISOString()
        : String(syncedRaw ?? "(无)");
    const ageMin
      = Number.isFinite(syncedMs) && syncedMs > 0
        ? Math.round((now - (syncedMs < 1e12 ? syncedMs * 1000 : syncedMs)) / 60000)
        : null;
    const stale = ageMin != null && ageMin > 60 ? " ⚠️ >1h 未刷新，可能被 archive" : "";
    console.log(
      `  ${r.platform} #${r.source_match_id} → match_id=${r.match_id ?? "NULL"} | ${r.home} vs ${r.away} | synced ${synced}${stale}`,
    );
  }
}

const vis = await pool.query(
  `SELECT COUNT(*)::int AS c FROM client_matches`,
);
console.log("\n── 汇总 ──");
console.log("  当前 Web 可见 client_matches 总数:", vis.rows[0].c);

const ferno = await pool.query(
  `SELECT id, title, matchs, built_at
   FROM client_matches
   WHERE title ILIKE '%Ferno%' OR title ILIKE '%Hastra%'
   ORDER BY id DESC LIMIT 5`,
);
if (ferno.rows.length) {
  console.log("\n── 队名含 Ferno/Hastra 的 client_matches ──");
  for (const r of ferno.rows) {
    console.log(`  #${r.id} | ${r.title} | matchs=${JSON.stringify(r.matchs)}`);
  }
}

const bySrc = await pool.query(
  `SELECT id, title, matchs
   FROM client_matches
   WHERE matchs::text LIKE '%38398938%' OR matchs::text LIKE '%373860%'
   LIMIT 5`,
);
if (bySrc.rows.length) {
  console.log("\n── matchs 含 RAY/IA source id 的行 ──");
  for (const r of bySrc.rows) {
    console.log(`  #${r.id} | ${r.title}`);
  }
}

await pool.end();

