if (!process.env.DATABASE_RDS_TARGET)
  process.env.DATABASE_RDS_TARGET = "public";

const { ensurePgPoolReady } = await import("@changmen/db");
const pool = await ensurePgPoolReady();
if (!pool) {
  console.error("DATABASE_URL 未配置");
  process.exit(1);
}

const { rows: profiles } = await pool.query(
  `SELECT id, user_name FROM profiles WHERE user_name IN ($1, $2)`,
  [KEEP_USER, DROP_USER],
);
const keepUserId = profiles.find(p => p.user_name === KEEP_USER)?.id;
const dropUserId = profiles.find(p => p.user_name === DROP_USER)?.id;
if (!keepUserId || !dropUserId) {
  console.error(`缺少用户 ${KEEP_USER}/${DROP_USER}`, profiles);
  await pool.end();
  process.exit(1);
}

const { rows: dupOids } = await pool.query(
  `
  SELECT lower(order_id) AS oid
  FROM ${financialOrdersRelation()}
  WHERE order_id IS NOT NULL AND trim(order_id) <> ''
    AND user_id IN ($1::uuid, $2::uuid)
  GROUP BY lower(order_id)
  HAVING COUNT(DISTINCT user_id) > 1
     AND bool_or(user_id = $1::uuid)
     AND bool_or(user_id = $2::uuid)
  `,
  [keepUserId, dropUserId],
);
const oids = dupOids.map(r => r.oid);
console.log(`mode=${dryRun ? "dry-run" : "execute"} keep=${KEEP_USER} drop=${DROP_USER}`);
console.log(`cross-user dup order_id groups: ${oids.length} (expect ${EXPECTED})`);

if (oids.length !== EXPECTED) {
  console.warn(`warn: expected ${EXPECTED} groups, found ${oids.length}`);
}

const keepRows = await pool.query(
  `
  SELECT o.id, o.order_id, o.player_id, o.provider, o.status, o.money, o.bet_money, o.link, o.create_at
  FROM ${financialOrdersRelation("o")}
  WHERE o.user_id = $1::uuid
    AND lower(o.order_id) = ANY($2::text[])
  ORDER BY o.order_id, o.id
  `,
  [keepUserId, oids],
);
const dropRows = await pool.query(
  `
  SELECT o.id, o.order_id, o.player_id, o.provider, o.status, o.money, o.bet_money, o.link, o.create_at
  FROM ${financialOrdersRelation("o")}
  WHERE o.user_id = $1::uuid
    AND lower(o.order_id) = ANY($2::text[])
  ORDER BY o.order_id, o.id
  `,
  [dropUserId, oids],
);

console.log(`keep ${KEEP_USER}: ${keepRows.rows.length} rows`);
console.log(`drop ${DROP_USER}: ${dropRows.rows.length} rows`);
for (const r of dropRows.rows) {
  console.log(
    `  DROP id=${r.id} order=${r.order_id} player=${r.player_id} ${r.provider} ${r.status} money=${r.money} link=${r.link}`,
  );
}

if (dropRows.rows.length !== EXPECTED) {
  console.warn(`warn: expected ${EXPECTED} drop rows, found ${dropRows.rows.length}`);
}
if (keepRows.rows.length < 1) {
  console.error("abort: keep 侧无行");
  await pool.end();
  process.exit(1);
}

if (dryRun) {
  console.log("\n[dry-run] 无变更");
  console.log(`备份表将为: ${BACKUP_KEEP} (保留侧) / ${BACKUP_DROP} (删除侧)`);
  console.log("执行: DATABASE_RDS_TARGET=public node server/backend/scripts/ops/incidents/cleanup-gb15-cross-dup-keep-gb14.mjs --execute");
  await pool.end();
  process.exit(0);
}

const keepIds = keepRows.rows.map(r => Number(r.id));
const dropIds = dropRows.rows.map(r => Number(r.id));
const client = await pool.connect();
try {
  await client.query("BEGIN");
  await client.query(`DROP TABLE IF EXISTS ${BACKUP_KEEP}`);
  await client.query(`DROP TABLE IF EXISTS ${BACKUP_DROP}`);
  await client.query(
    `CREATE TABLE ${BACKUP_KEEP} AS SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [keepIds],
  );
  await client.query(
    `CREATE TABLE ${BACKUP_DROP} AS SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [dropIds],
  );
  const bakKeep = await client.query(`SELECT COUNT(*)::int AS n FROM ${BACKUP_KEEP}`);
  const bakDrop = await client.query(`SELECT COUNT(*)::int AS n FROM ${BACKUP_DROP}`);
  const del = await client.query(
    `DELETE FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[]) AND user_id = $2::uuid`,
    [dropIds, dropUserId],
  );
  await client.query("COMMIT");
  console.log(`\n备份 ${BACKUP_KEEP}: ${bakKeep.rows[0].n} 行`);
  console.log(`备份 ${BACKUP_DROP}: ${bakDrop.rows[0].n} 行`);
  console.log(`已从 ${DROP_USER} 删除 ${del.rowCount ?? 0} 行；${KEEP_USER} 保留不动`);
}
catch (err) {
  await client.query("ROLLBACK");
  console.error("rollback:", err.message);
  process.exit(1);
}
finally {
  client.release();
}

const left = await pool.query(
  `
  SELECT pr.user_name, COUNT(*)::int AS n
  FROM ${financialOrdersRelation("o")}
  JOIN profiles pr ON pr.id = o.user_id
  WHERE lower(o.order_id) = ANY($1::text[])
    AND o.user_id IN ($2::uuid, $3::uuid)
  GROUP BY pr.user_name
  ORDER BY pr.user_name
  `,
  [oids, keepUserId, dropUserId],
);
const stillCross = await pool.query(
  `
  SELECT COUNT(*)::int AS n FROM (
    SELECT lower(order_id)
    FROM ${financialOrdersRelation()}
    WHERE order_id IS NOT NULL AND trim(order_id) <> ''
      AND user_id IN ($1::uuid, $2::uuid)
    GROUP BY lower(order_id)
    HAVING COUNT(DISTINCT user_id) > 1
  ) t
  `,
  [keepUserId, dropUserId],
);
console.log("after by user:", left.rows);
console.log(`remaining GB14↔GB15 cross dups: ${stillCross.rows[0].n}`);
await pool.end();

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * GB18 ↔ GB19 平博交叉同步：9 个相同 order_id 各写两份。
 * 真单在 GB19 player 252（jiayu1 / RMB54556WIJ，有 PM/RAY 对家腿）。
 * GB18 player 233 上的副本是错误活标签同步，删除。
 *
 *   DATABASE_RDS_TARGET=public node server/backend/scripts/ops/incidents/cleanup-gb18-gb19-pb-cross-dups.mjs
 *   DATABASE_RDS_TARGET=public node server/backend/scripts/ops/incidents/cleanup-gb18-gb19-pb-cross-dups.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

const dryRun = !process.argv.includes("--execute");
const KEEP_USER = "GB19";
const DROP_USER = "GB18";
const KEEP_PLAYER = 252;
const DROP_PLAYER = 233;
const STAMP = "20260914";
const BACKUP_KEEP = `orders_dup_backup_gb19_keep_pb_${STAMP}`;
const BACKUP_DROP = `orders_dup_backup_gb18_drop_pb_${STAMP}`;
const OIDS = [
  "767023318",
  "767023326",
  "767035000",
  "767035868",
  "767097374",
  "767257930",
  "767267916",
  "767268335",
  "767269823",
];

loadChangmenEnv();
if (!process.env.DATABASE_RDS_TARGET)
  process.env.DATABASE_RDS_TARGET = "public";

const { ensurePgPoolReady } = await import("@changmen/db");
const pool = await ensurePgPoolReady();
if (!pool) {
  console.error("DATABASE_URL 未配置");
  process.exit(1);
}

const { rows: profiles } = await pool.query(
  `SELECT id, user_name FROM profiles WHERE lower(user_name) IN ('gb18', 'gb19')`,
);
const keepUserId = profiles.find(p => String(p.user_name).toLowerCase() === "gb19")?.id;
const dropUserId = profiles.find(p => String(p.user_name).toLowerCase() === "gb18")?.id;
if (!keepUserId || !dropUserId) {
  console.error(`缺少用户 ${KEEP_USER}/${DROP_USER}`, profiles);
  await pool.end();
  process.exit(1);
}

const keepRows = await pool.query(
  `
  SELECT o.id, o.order_id, o.player_id, o.provider, o.status, o.money, o.bet_money, o.link, o.create_at
  FROM ${financialOrdersRelation("o")}
  WHERE o.user_id = $1::uuid
    AND o.player_id = $2
    AND upper(o.provider) = 'PB'
    AND o.order_id = ANY($3::text[])
  ORDER BY o.order_id, o.id
  `,
  [keepUserId, KEEP_PLAYER, OIDS],
);
const dropRows = await pool.query(
  `
  SELECT o.id, o.order_id, o.player_id, o.provider, o.status, o.money, o.bet_money, o.link, o.create_at
  FROM ${financialOrdersRelation("o")}
  WHERE o.user_id = $1::uuid
    AND o.player_id = $2
    AND upper(o.provider) = 'PB'
    AND o.order_id = ANY($3::text[])
  ORDER BY o.order_id, o.id
  `,
  [dropUserId, DROP_PLAYER, OIDS],
);

console.log(`mode=${dryRun ? "dry-run" : "execute"} keep=${KEEP_USER}/p${KEEP_PLAYER} drop=${DROP_USER}/p${DROP_PLAYER}`);
console.log(`keep rows=${keepRows.rows.length} drop rows=${dropRows.rows.length} expect=${OIDS.length}`);

const keepOids = new Set(keepRows.rows.map(r => String(r.order_id)));
const dropOids = new Set(dropRows.rows.map(r => String(r.order_id)));
for (const oid of OIDS) {
  if (!keepOids.has(oid)) {
    console.error(`abort: GB19 缺少 keep 行 ${oid}`);
    await pool.end();
    process.exit(1);
  }
  if (!dropOids.has(oid)) {
    console.error(`abort: GB18 缺少 drop 行 ${oid}`);
    await pool.end();
    process.exit(1);
  }
}
if (keepRows.rows.length !== OIDS.length || dropRows.rows.length !== OIDS.length) {
  console.error("abort: 行数与清单不一致，拒绝删除");
  await pool.end();
  process.exit(1);
}

for (const r of dropRows.rows) {
  console.log(
    `  DROP id=${r.id} order=${r.order_id} player=${r.player_id} ${r.status} money=${r.money} link=${r.link}`,
  );
}

if (dryRun) {
  console.log("\n[dry-run] 无变更");
  console.log(`备份表将为: ${BACKUP_KEEP} / ${BACKUP_DROP}`);
  console.log("执行加 --execute");
  await pool.end();
  process.exit(0);
}

const keepIds = keepRows.rows.map(r => Number(r.id));
const dropIds = dropRows.rows.map(r => Number(r.id));
const client = await pool.connect();
try {
  await client.query("BEGIN");
  await client.query(`DROP TABLE IF EXISTS ${BACKUP_KEEP}`);
  await client.query(`DROP TABLE IF EXISTS ${BACKUP_DROP}`);
  await client.query(
    `CREATE TABLE ${BACKUP_KEEP} AS SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [keepIds],
  );
  await client.query(
    `CREATE TABLE ${BACKUP_DROP} AS SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [dropIds],
  );
  const bakKeep = await client.query(`SELECT COUNT(*)::int AS n FROM ${BACKUP_KEEP}`);
  const bakDrop = await client.query(`SELECT COUNT(*)::int AS n FROM ${BACKUP_DROP}`);
  if (bakKeep.rows[0].n !== OIDS.length || bakDrop.rows[0].n !== OIDS.length) {
    throw new Error(`备份行数不对 keep=${bakKeep.rows[0].n} drop=${bakDrop.rows[0].n}`);
  }
  const del = await client.query(
    `DELETE FROM ${financialOrdersRelation()}
     WHERE id = ANY($1::bigint[])
       AND user_id = $2::uuid
       AND player_id = $3
       AND upper(provider) = 'PB'`,
    [dropIds, dropUserId, DROP_PLAYER],
  );
  if ((del.rowCount ?? 0) !== OIDS.length) {
    throw new Error(`删除行数 ${del.rowCount} != ${OIDS.length}`);
  }
  await client.query("COMMIT");
  console.log(`\n备份 ${BACKUP_KEEP}: ${bakKeep.rows[0].n} 行`);
  console.log(`备份 ${BACKUP_DROP}: ${bakDrop.rows[0].n} 行`);
  console.log(`已从 ${DROP_USER} p${DROP_PLAYER} 删除 ${del.rowCount} 行；${KEEP_USER} 保留不动`);
}
catch (err) {
  await client.query("ROLLBACK");
  console.error("rollback:", err.message);
  process.exit(1);
}
finally {
  client.release();
}

const left = await pool.query(
  `
  SELECT pr.user_name, o.player_id, COUNT(*)::int AS n
  FROM ${financialOrdersRelation("o")}
  JOIN profiles pr ON pr.id = o.user_id
  WHERE o.order_id = ANY($1::text[])
    AND o.user_id IN ($2::uuid, $3::uuid)
  GROUP BY pr.user_name, o.player_id
  ORDER BY pr.user_name
  `,
  [OIDS, keepUserId, dropUserId],
);
const stillCross = await pool.query(
  `
  SELECT COUNT(*)::int AS n FROM (
    SELECT lower(order_id)
    FROM ${financialOrdersRelation()}
    WHERE order_id = ANY($1::text[])
      AND user_id IN ($2::uuid, $3::uuid)
    GROUP BY lower(order_id)
    HAVING COUNT(DISTINCT user_id) > 1
  ) t
  `,
  [OIDS, keepUserId, dropUserId],
);
console.log("after by user:", left.rows);
console.log(`remaining cross dups on these 9 ids: ${stillCross.rows[0].n}`);
await pool.end();

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * River PM：删除 player_id=45 上与 player_id=47 重复的订单副本。
 * Usage:
 *   node scripts/cleanup-river-pm-player45-dupes.mjs --dry-run
 *   node scripts/cleanup-river-pm-player45-dupes.mjs
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

const dryRun = process.argv.includes("--dry-run");
const RIVER_USER = "River";
const KEEP_PLAYER = 47;
const DROP_PLAYER = 45;
const PROVIDER = "Polymarket";
const BACKUP_TABLE = "orders_dup_backup_river_pm45_20260712";

loadChangmenEnv();
const { initDatabaseUrl, getPgPool } = await import("@changmen/db");
await initDatabaseUrl();
const pool = getPgPool();

if (!pool) {
  console.error("DATABASE_URL 未配置");
  process.exit(1);
}

const { rows: users } = await pool.query(
  `SELECT id, user_name FROM users WHERE user_name ILIKE $1 LIMIT 1`,
  [RIVER_USER],
);
const userId = users[0]?.id;
if (!userId) {
  console.error(`用户 ${RIVER_USER} 不存在`);
  process.exit(1);
}

const preview = await pool.query(
  `SELECT o.id, o.order_id, o.player_id, o.status, o.bet_money, o.money, o.create_at,
          to_char(to_timestamp(o.create_at / 1000.0), 'YYYY-MM-DD HH24:MI:SS') AS create_at_local
   FROM ${financialOrdersRelation("o")}
   WHERE o.user_id = $1::uuid
     AND o.player_id = $2
     AND o.provider = $3
     AND EXISTS (
       SELECT 1 FROM ${financialOrdersRelation("k")}
       WHERE k.user_id = o.user_id
         AND k.player_id = $4
         AND k.order_id = o.order_id
     )
   ORDER BY o.create_at DESC, o.order_id`,
  [userId, DROP_PLAYER, PROVIDER, KEEP_PLAYER],
);

const orphan45 = await pool.query(
  `SELECT COUNT(*)::int AS n
   FROM ${financialOrdersRelation("o")}
   WHERE o.user_id = $1::uuid
     AND o.player_id = $2
     AND o.provider = $3
     AND NOT EXISTS (
       SELECT 1 FROM ${financialOrdersRelation("k")}
       WHERE k.user_id = o.user_id
         AND k.player_id = $4
         AND k.order_id = o.order_id
     )`,
  [userId, DROP_PLAYER, PROVIDER, KEEP_PLAYER],
);

console.log(`user=${users[0].user_name} (${userId})`);
console.log(`will delete ${preview.rows.length} duplicate rows (player ${DROP_PLAYER}, keep ${KEEP_PLAYER})`);
console.log(`player ${DROP_PLAYER} PM orders without player ${KEEP_PLAYER} counterpart: ${orphan45.rows[0].n}`);

for (const row of preview.rows.slice(0, 15))
  console.log(`  id=${row.id} order_id=${row.order_id} status=${row.status} at=${row.create_at_local}`);
if (preview.rows.length > 15)
  console.log(`  ... and ${preview.rows.length - 15} more`);

if (!preview.rows.length) {
  console.log("nothing to delete");
  await pool.end();
  process.exit(0);
}

if (dryRun) {
  console.log("[dry-run] no changes");
  await pool.end();
  process.exit(0);
}

const ids = preview.rows.map(r => Number(r.id)).filter(n => Number.isFinite(n) && n > 0);
const client = await pool.connect();

try {
  await client.query("BEGIN");

  await client.query(`DROP TABLE IF EXISTS ${BACKUP_TABLE}`);
  const backup = await client.query(
    `CREATE TABLE ${BACKUP_TABLE} AS
     SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [ids],
  );

  const del = await client.query(
    `DELETE FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [ids],
  );

  await client.query("COMMIT");
  console.log(`backup table: ${BACKUP_TABLE} (${backup.rowCount ?? ids.length} rows)`);
  console.log(`deleted ${del.rowCount ?? 0} rows`);
}
catch (err) {
  await client.query("ROLLBACK");
  console.error("rollback:", err.message);
  process.exit(1);
}
finally {
  client.release();
  await pool.end();
}

