#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 回填 PM Reject 金额单位错误：
 * - bug：persist 把 checkBetting 后的 USDC 写进 bet_money，再被 ÷汇率当成 pmStakeUsdc
 * - 正确：pmStakeUsdc = 真实 U，bet_money = U × 汇率（CNY）；reward/money 拒单应为 0
 *
 * 幂等：写入 raw.pmRejectMoneyFixedAt；已标记的跳过。
 * 识别：把 bet 当 U 得到的份额≈正常 FOK（20–120），而 stake×odds 明显偏小。
 *
 *   node scripts/ops/incidents/fix-pm-reject-money-units.mjs --dry-run
 *   node scripts/ops/incidents/fix-pm-reject-money-units.mjs --user GB18 --dry-run
 *   node scripts/ops/incidents/fix-pm-reject-money-units.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

const FX = getExchange(Currency.USDT);

function parseArgs(argv) {
  const out = { dryRun: true, userName: "", help: false, limit: 0 };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--limit")
      out.limit = Math.max(0, Number(argv[++i]) || 0);
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function num(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function round4(n) {
  return Math.round(n * 10000) / 10000;
}

/**
 * bet_money 被误存为 USDC：bet×odds ≈ 真实份额；pmStakeUsdc 被误写成 bet/fx。
 * 已修好：stake×odds ≈ 真实份额，bet×odds 会大一截（CNY×odds）。
 *
 * 另有半修复：bet 已乘汇率成 CNY，但 stake 仍是「U/汇率」→ bet/stake ≈ fx²。
 */
export function classifyPmRejectMoneyBug(row) {
  const raw = rawObj(row);
  if (String(raw.pmRejectMoneyFixedAt ?? "").trim())
    return null;
  if (String(raw.pmOrigin ?? "").toLowerCase() !== "changmen")
    return null;
  if (String(raw.pmSide ?? "buy").toLowerCase() === "sell")
    return null;
  const bet = num(row.bet_money);
  const stake = num(raw.pmStakeUsdc);
  const odds = num(row.odds);
  // 无 stake 不猜：CNY 小单 × odds 可落入份额带，易误判 inverted
  if (!(bet > 0) || !(stake > 0) || !(odds > 1))
    return null;

  // 半修复：CNY 已对，stake 仍小一档（bet/stake ≈ fx²）
  const ratio = bet / stake;
  if (Math.abs(ratio - FX * FX) <= FX * FX * 0.03) {
    return {
      kind: "half_fixed",
      newStake: round4(bet / FX),
      newBet: round4(bet),
    };
  }

  const sharesIfBetUsdc = bet * odds;
  if (sharesIfBetUsdc < 15 || sharesIfBetUsdc > 200)
    return null;
  const sharesIfStakeUsdc = stake * odds;
  if (!(sharesIfStakeUsdc < sharesIfBetUsdc / 3))
    return null;
  // 旧 sync：pmStakeUsdc ≈ bet_money(U) / fx
  if (Math.abs(stake * FX - bet) > Math.max(0.05, bet * 0.02))
    return null;
  return {
    kind: "inverted",
    newStake: round4(bet),
    newBet: round4(bet * FX),
  };
}

/** @deprecated 兼容旧调用名 */
export function isInvertedPmRejectMoney(row) {
  return Boolean(classifyPmRejectMoneyBug(row));
}

function planFix(row) {
  const raw = rawObj(row);
  const classified = classifyPmRejectMoneyBug(row);
  if (!classified)
    return null;
  const oldBet = num(row.bet_money);
  const oldStake = num(raw.pmStakeUsdc);
  return {
    orderId: String(row.order_id),
    userId: String(row.user_id),
    kind: classified.kind,
    oldBet,
    oldStake,
    newBet: classified.newBet,
    newStake: classified.newStake,
    odds: num(row.odds),
    oldReward: num(raw.reward),
    nextRaw: {
      ...raw,
      betMoney: classified.newBet,
      pmStakeUsdc: classified.newStake,
      reward: 0,
      money: 0,
      status: "reject",
      pmSide: "buy",
      pmOrigin: "changmen",
      pmRejectMoneyFixedAt: Date.now(),
    },
  };
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/incidents/fix-pm-reject-money-units.mjs [--user NAME] [--limit N] [--dry-run|--execute]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();
  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  const profiles = await fetchProfiles();
  const nameById = new Map();
  for (const p of profiles) {
    const id = String(p.id ?? p.user_id ?? "");
    nameById.set(id, String(p.user_name ?? p.userName ?? id).trim());
  }

  const wantUser = args.userName.toLowerCase();
  const { rows } = await pool.query(`
    SELECT id, user_id, order_id, bet_money, money, odds, status, raw, create_at
    FROM ${financialOrdersRelation()}
    WHERE provider = 'Polymarket'
      AND lower(status) = 'reject'
    ORDER BY create_at
  `);

  const candidates = [];
  for (const row of rows) {
    const uname = nameById.get(String(row.user_id)) || String(row.user_id);
    if (wantUser && uname.toLowerCase() !== wantUser)
      continue;
    const planned = planFix(row);
    if (!planned)
      continue;
    candidates.push({ ...planned, userName: uname, createAt: row.create_at, id: row.id });
  }

  const list = args.limit > 0 ? candidates.slice(0, args.limit) : candidates;
  const byKind = list.reduce((m, c) => {
    m[c.kind] = (m[c.kind] || 0) + 1;
    return m;
  }, {});
  console.log(`[scan] reject rows=${rows.length} fixable=${candidates.length} apply=${list.length} kinds=${JSON.stringify(byKind)} fx=${FX} mode=${args.dryRun ? "dry-run" : "execute"}`);
  for (const c of list.slice(0, 30)) {
    console.log({
      user: c.userName,
      kind: c.kind,
      order: c.orderId.slice(0, 18),
      bet: `${c.oldBet} → ${c.newBet}`,
      stake: `${c.oldStake} → ${c.newStake}`,
      odds: c.odds,
      reward: `${c.oldReward} → 0`,
    });
  }
  if (list.length > 30)
    console.log(`… +${list.length - 30} more`);

  if (args.dryRun) {
    console.log("[dry-run] no writes");
    await pool.end?.();
    process.exit(0);
  }

  let updated = 0;
  for (const c of list) {
    const r = await pool.query(
      `UPDATE ${financialOrdersRelation()}
       SET bet_money = $1,
           money = 0,
           raw = $2::jsonb
       WHERE id = $3
         AND lower(status) = 'reject'
         AND coalesce(raw->>'pmRejectMoneyFixedAt', '') = ''
       RETURNING id`,
      [c.newBet, JSON.stringify(c.nextRaw), c.id],
    );
    if (r.rowCount)
      updated += 1;
  }
  console.log(`[execute] updated ${updated} rows`);
  await pool.end?.();
}

const isDirectRun = process.argv[1]
  && String(process.argv[1]).endsWith("fix-pm-reject-money-units.mjs");
if (isDirectRun) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 清 PM 卖光买单残留 pmStakeUsdc（巡检 pm_sold_out_but_stake_left）
 *
 * 仅改 raw.pmStakeUsdc → 0；不动 money / bet_money / pmSellState。
 *
 *   node scripts/ops/incidents/fix-pm-sold-out-stake-left.mjs --dry-run
 *   node scripts/ops/incidents/fix-pm-sold-out-stake-left.mjs --user River --dry-run
 *   node scripts/ops/incidents/fix-pm-sold-out-stake-left.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

const PM_SHARE_DUST = 0.01;

function parseArgs(argv) {
  const out = { dryRun: true, userName: "", help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function num(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function shortId(id) {
  const s = String(id ?? "");
  return s.length > 14 ? `${s.slice(0, 10)}…` : s;
}

function shTime(ms) {
  const t = Number(ms) || 0;
  if (!t)
    return "";
  return new Date(t).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false });
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/incidents/fix-pm-sold-out-stake-left.mjs [--user NAME] [--dry-run|--execute]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();
  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  const profiles = await fetchProfiles();
  const nameById = new Map();
  for (const p of profiles) {
    const id = String(p.id ?? p.user_id ?? "");
    nameById.set(id, String(p.user_name ?? p.userName ?? id).trim());
  }

  const wantUser = args.userName.toLowerCase();
  const { rows } = await pool.query(`
    SELECT id, user_id, player_id, order_id, match, item, money, bet_money, status, create_at, raw
    FROM ${financialOrdersRelation()}
    WHERE LOWER(COALESCE(provider, '')) = 'polymarket'
      AND LOWER(COALESCE(raw->>'pmSide', 'buy')) <> 'sell'
  `);

  const issues = [];
  for (const row of rows) {
    const userName = nameById.get(String(row.user_id ?? "")) || String(row.user_id ?? "");
    if (wantUser && userName.toLowerCase() !== wantUser)
      continue;

    const raw = rawObj(row);
    const fill = num(raw.pmShares);
    const attr = num(raw.pmAttributedSellShares);
    const rem = Math.round(Math.max(0, fill - attr) * 10000) / 10000;
    const remEff = rem <= PM_SHARE_DUST ? 0 : rem;
    const stake = num(raw.pmStakeUsdc);
    const state = String(raw.pmSellState ?? "").toLowerCase();

    if (remEff !== 0)
      continue;
    if (!(attr > 0 || state === "closed" || state === "settled" || state === "partial"))
      continue;
    if (!(stake > 0.05))
      continue;

    issues.push({
      id: row.id,
      user: userName,
      playerId: row.player_id,
      orderId: String(row.order_id),
      match: row.match,
      item: row.item,
      money: num(row.money),
      betMoney: num(row.bet_money),
      status: row.status,
      createAtShanghai: shTime(row.create_at),
      fill,
      attr,
      stake,
      state,
      raw,
    });
  }

  console.log(JSON.stringify({
    mode: args.dryRun ? "dry-run" : "execute",
    userFilter: args.userName || null,
    issueCount: issues.length,
    issues: issues.map(i => ({
      user: i.user,
      playerId: i.playerId,
      orderId: shortId(i.orderId),
      match: i.match,
      item: i.item,
      money: i.money,
      betMoney: i.betMoney,
      status: i.status,
      createAtShanghai: i.createAtShanghai,
      fill: i.fill,
      attr: i.attr,
      stake: i.stake,
      state: i.state,
    })),
  }, null, 2));

  if (args.dryRun) {
    console.log("[dry-run] no writes");
    process.exit(0);
  }

  let updated = 0;
  for (const i of issues) {
    const nextRaw = { ...i.raw, pmStakeUsdc: 0 };
    await pool.query(
      `UPDATE ${financialOrdersRelation()} SET raw = $2::jsonb WHERE id = $1`,
      [i.id, JSON.stringify(nextRaw)],
    );
    updated += 1;
  }
  console.log(`[execute] updated ${updated} rows (pmStakeUsdc → 0)`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * GB12 PM：将 player 76/102 订单归属到 105。
 * - 同一 order_id 只保留一行（优先 link 与 OB 等套利腿一致的行）
 * - 仅 UPDATE player_id，不修改 link 及其他字段
 *
 * Usage:
 *   node scripts/migrate-gb12-pm-orders-to-105.mjs --dry-run
 *   node scripts/migrate-gb12-pm-orders-to-105.mjs
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

const dryRun = process.argv.includes("--dry-run");
const USER_NAME = "GB12";
const FROM_PLAYERS = [76, 102];
const TO_PLAYER = 105;
const PROVIDER = "Polymarket";
const BACKUP_TABLE = "orders_migrate_backup_gb12_pm_76_102_20260712";

loadChangmenEnv();
const { initDatabaseUrl, getPgPool } = await import("@changmen/db");
await initDatabaseUrl();
const pool = getPgPool();

if (!pool) {
  console.error("DATABASE_URL 未配置");
  process.exit(1);
}

const { rows: users } = await pool.query(
  `SELECT id, user_name FROM users WHERE user_name ILIKE $1 LIMIT 1`,
  [USER_NAME],
);
const userId = users[0]?.id;
if (!userId) {
  console.error(`用户 ${USER_NAME} 不存在`);
  process.exit(1);
}

const plan = await pool.query(
  `
  WITH candidates AS (
    SELECT o.id, o.user_id, o.player_id, o.order_id, o.link, o.status, o.create_at
    FROM ${financialOrdersRelation("o")}
    WHERE o.user_id = $1::uuid
      AND o.provider = $2
      AND o.player_id = ANY($3::bigint[])
  ),
  on105 AS (
    SELECT order_id FROM ${financialOrdersRelation()}
    WHERE user_id = $1::uuid AND provider = $2 AND player_id = $4
  ),
  arb_links AS (
    SELECT DISTINCT link
    FROM ${financialOrdersRelation()}
    WHERE user_id = $1::uuid
      AND provider <> $2
      AND link IS NOT NULL
      AND ABS(link) >= 1000000000000
  ),
  ranked AS (
    SELECT
      c.*,
      EXISTS (SELECT 1 FROM on105 t WHERE t.order_id = c.order_id) AS already_on_105,
      EXISTS (SELECT 1 FROM arb_links a WHERE a.link = c.link) AS link_has_arb_partner,
      ROW_NUMBER() OVER (
        PARTITION BY c.order_id
        ORDER BY
          CASE WHEN EXISTS (SELECT 1 FROM arb_links a WHERE a.link = c.link) THEN 0 ELSE 1 END,
          CASE WHEN c.player_id = 76 THEN 0 WHEN c.player_id = 102 THEN 1 ELSE 2 END,
          c.id
      ) AS rn,
      COUNT(*) OVER (PARTITION BY c.order_id)::int AS dup_cnt
    FROM candidates c
  )
  SELECT *
  FROM ranked
  ORDER BY order_id, rn
  `,
  [userId, PROVIDER, FROM_PLAYERS, TO_PLAYER],
);

const keepRows = plan.rows.filter(r => Number(r.rn) === 1);
const deleteRows = plan.rows.filter(r => Number(r.rn) > 1);
const migrateRows = keepRows.filter(r => !r.already_on_105);
const skipDeleteKeepers = keepRows.filter(r => r.already_on_105);

console.log(`user=${users[0].user_name} (${userId})`);
console.log(`source players: ${FROM_PLAYERS.join(", ")} -> ${TO_PLAYER}`);
console.log(`distinct order_id: ${keepRows.length}`);
console.log(`migrate (UPDATE player_id): ${migrateRows.length}`);
console.log(`delete duplicates: ${deleteRows.length + skipDeleteKeepers.length}`);

for (const row of plan.rows) {
  const action = Number(row.rn) > 1
    ? "DELETE"
    : row.already_on_105
      ? "DELETE (105 exists)"
      : "MIGRATE";
  console.log(
    `  [${action}] id=${row.id} player=${row.player_id} order=${String(row.order_id).slice(0, 18)}... link=${row.link} arb=${row.link_has_arb_partner}`,
  );
}

if (!plan.rows.length) {
  console.log("nothing to do");
  await pool.end();
  process.exit(0);
}

if (dryRun) {
  console.log("[dry-run] no changes");
  await pool.end();
  process.exit(0);
}

const deleteIds = [
  ...deleteRows.map(r => Number(r.id)),
  ...skipDeleteKeepers.map(r => Number(r.id)),
].filter(n => Number.isFinite(n) && n > 0);
const migrateIds = migrateRows.map(r => Number(r.id)).filter(n => Number.isFinite(n) && n > 0);
const backupIds = [...new Set([...deleteIds, ...migrateIds])];

const client = await pool.connect();

try {
  await client.query("BEGIN");

  await client.query(`DROP TABLE IF EXISTS ${BACKUP_TABLE}`);
  await client.query(
    `CREATE TABLE ${BACKUP_TABLE} AS
     SELECT * FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`,
    [backupIds],
  );

  if (deleteIds.length) {
    await client.query(`DELETE FROM ${financialOrdersRelation()} WHERE id = ANY($1::bigint[])`, [deleteIds]);
  }

  if (migrateIds.length) {
    const upd = await client.query(
      `UPDATE ${financialOrdersRelation()} SET player_id = $1
       WHERE id = ANY($2::bigint[]) AND user_id = $3::uuid`,
      [TO_PLAYER, migrateIds, userId],
    );
    if ((upd.rowCount ?? 0) !== migrateIds.length)
      throw new Error(`migrate rowCount mismatch: expected ${migrateIds.length}, got ${upd.rowCount}`);
  }

  await client.query("COMMIT");
  console.log(`backup: ${BACKUP_TABLE} (${backupIds.length} rows)`);
  console.log(`deleted ${deleteIds.length}, migrated ${migrateIds.length}`);
}
catch (err) {
  await client.query("ROLLBACK");
  console.error("rollback:", err.message);
  process.exit(1);
}
finally {
  client.release();
  await pool.end();
}

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * GB13：软删 player 订单迁到活跃 successor；player 77（米兰）按方案 A 保留不动。
 *
 *   node scripts/migrate-gb13-soft-deleted-orders.mjs --dry-run
 *   node scripts/migrate-gb13-soft-deleted-orders.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

const dryRun = !process.argv.includes("--execute");
const USER_NAME = "GB13";
const BACKUP_TABLE = "orders_migrate_backup_gb13_soft_20260712";

/** 软删 player -> 活跃 successor（77 无映射，跳过） */
const SUCCESSOR = new Map([
  [78, 118],
  [106, 118],
  [80, 111],
  [84, 119],
  [107, 111],
]);

/** 软删间重复：删 106 副本，保留 78（link 有活跃 RAY/PB 对腿） */
const DELETE_IDS = [2013540, 2013539];

/** 明确迁移行（RDS orders.id）；由 _tmp_gb13_soft_migrate_plan.mjs 核对 */
const MIGRATE_ROWS = [
  { id: 1311129, from: 78, to: 118 },
  { id: 1302452, from: 78, to: 118 },
  { id: 1267729, from: 78, to: 118 },
  { id: 1276215, from: 78, to: 118 },
  { id: 1709034, from: 78, to: 118 },
  { id: 1728751, from: 78, to: 118 },
  { id: 2013541, from: 106, to: 118 },
  { id: 2013538, from: 106, to: 118 },
  { id: 1302728, from: 80, to: 111 },
  { id: 1271848, from: 80, to: 111 },
  { id: 1286884, from: 80, to: 111 },
  { id: 1391026, from: 80, to: 111 },
  { id: 1721141, from: 84, to: 119 },
  { id: 1725504, from: 84, to: 119 },
