#!/usr/bin/env node
/**
 * 核对 storage/*.json 与 RDS tag_platforms/players 是否一致。
 *
 *   cd changmen/server/backend && node scripts/ops/migrations/check-players-rds-migrate.mjs
 */

import { getPgPool, initDatabaseUrl } from "@changmen/db";
import { readJsonFile } from "@changmen/storage/json_file_store.js";

function rowId(row) {
  return Number(row?.id ?? row?.ID ?? row?.playerId ?? 0);
}

await initDatabaseUrl();
const pool = getPgPool();
if (!pool) {
  console.error("[check] 无 DATABASE_URL");
  process.exit(1);
}

const tagJson = readJsonFile("tag_platforms", {}) || {};
const playersJson = readJsonFile("players", {}) || {};
const tpEntries = Object.values(tagJson);
const plEntries = Object.values(playersJson);

const { rows: [counts] } = await pool.query(`
  SELECT
    (SELECT COUNT(*)::int FROM tag_platforms) AS tag_platforms,
    (SELECT COUNT(*)::int FROM players) AS players,
    (SELECT COUNT(*)::int FROM players WHERE deleted_at IS NULL) AS players_active
`);

const tpIds = tpEntries.map(rowId).filter(Boolean);
const plIds = plEntries.map(rowId).filter(Boolean);

const missingTp = [];
if (tpIds.length) {
  const { rows } = await pool.query(
    "SELECT id FROM tag_platforms WHERE id = ANY($1::bigint[])",
    [tpIds],
  );
  const have = new Set(rows.map(r => Number(r.id)));
  for (const id of tpIds) {
    if (!have.has(id))
      missingTp.push(id);
  }
}

const missingPl = [];
if (plIds.length) {
  const { rows } = await pool.query(
    "SELECT id FROM players WHERE id = ANY($1::bigint[])",
    [plIds],
  );
  const have = new Set(rows.map(r => Number(r.id)));
  for (const id of plIds) {
    if (!have.has(id))
      missingPl.push(id);
  }
}

const { rows: [seq] } = await pool.query(`
  SELECT
    (SELECT MAX(id) FROM tag_platforms) AS max_tag_platform_id,
    (SELECT MAX(id) FROM players) AS max_player_id,
    (SELECT last_value FROM tag_platforms_id_seq) AS tag_platforms_seq,
    (SELECT last_value FROM players_id_seq) AS players_seq
`);

const ok
  = missingTp.length === 0
    && missingPl.length === 0
    && counts.tag_platforms > 0
    && counts.players >= plEntries.filter(r => rowId(r) && Number(r?.platformId ?? r?.platform_id)).length;

const report = {
  ok,
  json: {
    tagPlatforms: tpEntries.length,
    players: plEntries.length,
  },
  rds: counts,
  sequences: seq,
  missingInRds: {
    tagPlatformIds: missingTp,
    playerIds: missingPl,
  },
};

console.log("[check-players-rds]", JSON.stringify(report, null, 2));
process.exit(ok ? 0 : 1);

#!/usr/bin/env node
/**
 * 收尾：profile 引用的 player 补 owner_user_id；无引用活跃孤儿 soft-delete。
 * 前置：migrate-players-owner-user-id.mjs
 *
 *   node scripts/ops/migrations/finalize-players-owner-user-id.mjs [--dry-run]
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady, getPgPool } from "@changmen/db";

const dryRun = process.argv.includes("--dry-run");
loadChangmenEnv();
await ensurePgPoolReady();
const pool = getPgPool();

function accountIdOf(row) {
  return Number(row?.accountId ?? row?.AccountId) || 0;
}

const { rows: profiles } = await pool.query(`SELECT id, accounts FROM profiles`);
/** @type {Map<number, string>} */
const playerOwner = new Map();

for (const prof of profiles) {
  for (const acc of prof.accounts || []) {
    const pid = accountIdOf(acc);
    if (pid)
      playerOwner.set(pid, prof.id);
  }
}

const { rows: orphans } = await pool.query(
  `SELECT id, platform_name, player_name FROM players
   WHERE deleted_at IS NULL AND owner_user_id IS NULL
   ORDER BY id`,
);

let assigned = 0;
let deleted = 0;

for (const row of orphans) {
  const owner = playerOwner.get(Number(row.id));
  if (owner) {
    console.log(`${dryRun ? "[dry-run] " : ""}assign player ${row.id} → user ${owner}`);
    if (!dryRun) {
      await pool.query(
        `UPDATE players SET owner_user_id = $2, updated_at = $3 WHERE id = $1`,
        [row.id, owner, Date.now()],
      );
    }
    assigned += 1;
    continue;
  }
  console.log(`${dryRun ? "[dry-run] " : ""}soft-delete orphan player ${row.id} (${row.platform_name}/${row.player_name})`);
  if (!dryRun) {
    const now = Date.now();
    await pool.query(
      `UPDATE players SET deleted_at = $2, delete_description = $3, updated_at = $2
       WHERE id = $1 AND deleted_at IS NULL`,
      [row.id, now, "finalize-players-owner: no profile reference"],
    );
  }
  deleted += 1;
}

const { rows: left } = await pool.query(
  `SELECT COUNT(*)::int AS n FROM players WHERE deleted_at IS NULL AND owner_user_id IS NULL`,
);
console.log("done:", { assigned, deleted, activeWithoutOwner: left[0]?.n ?? 0 });
if ((left[0]?.n ?? 0) > 0) {
  console.warn("仍有活跃 player 无 owner，勿执行 027_players_active_owner_required.sql");
  process.exit(1);
}

#!/usr/bin/env node
/**
 * 一次性：profiles.accounts jsonb → players.account_data + 结构化列
 * 部署 028 之后执行；之后 SaveData 只写 players。
 *
 *   cd changmen/server/backend && node scripts/ops/migrations/migrate-accounts-jsonb-to-players.mjs
 *   node scripts/ops/migrations/migrate-accounts-jsonb-to-players.mjs --dry-run
 */
import "@changmen/storage/load_env.js";
import * as sb from "@changmen/db";
import { mergeJsonbAccountIntoPlayerPatch } from "../../../../db/player_account_record.js";
import { getPgPool } from "../../../../db/rds/common.js";

const dryRun = process.argv.includes("--dry-run");

async function main() {
  const pool = getPgPool();
  if (!pool) {
    console.error("DATABASE_URL required");
    process.exit(1);
  }
  try {
    const { rows: profiles } = await pool.query(
      `SELECT p.id, p.user_name, p.accounts
       FROM profiles p
       ORDER BY p.user_name`,
    );
    let merged = 0;
    let skipped = 0;
    let missingPlayer = 0;
    for (const p of profiles || []) {
      const uid = String(p.id);
      let accounts = [];
      try {
        accounts = Array.isArray(p.accounts) ? p.accounts : JSON.parse(p.accounts || "[]");
      }
      catch {
        accounts = [];
      }
      if (!accounts.length)
        continue;
      for (const row of accounts) {
        const playerId = Number(row?.accountId ?? row?.AccountId);
        if (!playerId) {
          skipped++;
          continue;
        }
        const player = await sb.fetchPlayerById(playerId);
        if (!player) {
          console.warn(`[migrate] ${p.user_name}: player ${playerId} 不存在，跳过`);
          missingPlayer++;
          continue;
        }
        if (player.ownerUserId && String(player.ownerUserId) !== uid) {
          console.warn(`[migrate] ${p.user_name}: player ${playerId} owner=${player.ownerUserId} 不匹配，跳过`);
          skipped++;
          continue;
        }
        const patch = mergeJsonbAccountIntoPlayerPatch(row, player);
        if (dryRun) {
          console.log(`[dry-run] ${p.user_name} player ${playerId} provider=${patch.provider} cred=${Boolean(patch.accountData?.gateway && patch.accountData?.token)}`);
          merged++;
          continue;
        }
        const ok = await sb.savePlayerAccountRecord(uid, {
          ...row,
          accountId: playerId,
          platformId: patch.platformId ?? player.platformId,
          platformName: patch.platformName || player.platformName,
          playerName: patch.playerName || player.playerName,
          provider: patch.provider,
          credit: patch.credit,
          balance: patch.totalBalance,
          ...patch.accountData,
        });
        if (ok)
          merged++;
        else
          skipped++;
      }
    }
    console.log("[migrate-accounts-jsonb-to-players] done:", {
      dryRun,
      merged,
      skipped,
      missingPlayer,
      profiles: profiles?.length ?? 0,
    });
  }
  finally {
    await pool.end();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

