#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 存量 players 回填 owner_user_id，并拆分多用户共用的 playerId。
 *
 * 前置：026_players_owner_user_id.sql 已执行
 *
 *   cd changmen/server/backend
 *   node scripts/ops/migrations/migrate-players-owner-user-id.mjs [--dry-run]
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady, getPgPool } from "@changmen/db";

const dryRun = process.argv.includes("--dry-run");
loadChangmenEnv();
await ensurePgPoolReady();
const pool = getPgPool();

function accountIdOf(row) {
  return Number(row?.accountId ?? row?.AccountId) || 0;
}

function replaceAccountId(accounts, oldId, newId) {
  let changed = false;
  const next = (accounts || []).map((row) => {
    if (accountIdOf(row) !== oldId)
      return row;
    changed = true;
    return { ...row, accountId: newId, AccountId: newId };
  });
  return changed ? next : accounts;
}

async function loadPlayerOwners() {
  /** @type {Map<number, Set<string>>} */
  const map = new Map();

  function add(playerId, userId) {
    const id = Number(playerId);
    const uid = String(userId || "").trim();
    if (!id || !uid)
      return;
    if (!map.has(id))
      map.set(id, new Set());
    map.get(id).add(uid);
  }

  const { rows: profiles } = await pool.query(`SELECT id, accounts FROM profiles`);
  for (const row of profiles) {
    for (const acc of row.accounts || []) {
      add(accountIdOf(acc), row.id);
    }
  }

  const { rows: orderOwners } = await pool.query(
    `SELECT DISTINCT user_id, player_id FROM ${financialOrdersRelation()} WHERE player_id > 0`,
  );
  for (const row of orderOwners) {
    add(row.player_id, row.user_id);
  }

  const { rows: logOwners } = await pool.query(
    `SELECT DISTINCT user_id, player_id FROM money_logs WHERE player_id > 0`,
  );
  for (const row of logOwners) {
    add(row.player_id, row.user_id);
  }

  return map;
}

async function orderCountByUser(playerId) {
  const { rows } = await pool.query(
    `SELECT user_id, COUNT(*)::int AS cnt
     FROM ${financialOrdersRelation()} WHERE player_id = $1
     GROUP BY user_id`,
    [playerId],
  );
  /** @type {Map<string, number>} */
  const map = new Map();
  for (const row of rows)
    map.set(String(row.user_id), Number(row.cnt) || 0);
  return map;
}

function pickPrimaryOwner(owners, orderCounts) {
  const list = [...owners].sort();
  let best = list[0];
  let bestCount = orderCounts.get(best) || 0;
  for (const uid of list.slice(1)) {
    const cnt = orderCounts.get(uid) || 0;
    if (cnt > bestCount || (cnt === bestCount && uid < best)) {
      best = uid;
      bestCount = cnt;
    }
  }
  return best;
}

async function clonePlayer(client, player, ownerUserId) {
  const now = Date.now();
  const { rows } = await client.query(
    `INSERT INTO players (
       owner_user_id, platform_id, platform_name, player_name,
       credit, total_balance, created_at, updated_at
     ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
     RETURNING id`,
    [
      ownerUserId,
      player.platform_id,
      player.platform_name,
      player.player_name,
      player.credit,
      player.total_balance,
      player.created_at || now,
      now,
    ],
  );
  return Number(rows[0]?.id) || 0;
}

async function updateProfileAccountId(client, userId, oldId, newId) {
  const { rows } = await client.query(
    `SELECT accounts FROM profiles WHERE id = $1`,
    [userId],
  );
  const accounts = rows[0]?.accounts || [];
  const next = replaceAccountId(accounts, oldId, newId);
  if (next === accounts)
    return false;
  await client.query(
    `UPDATE profiles SET accounts = $2::jsonb, updated_at = $3 WHERE id = $1`,
    [userId, JSON.stringify(next), Date.now()],
  );
  return true;
}

async function main() {
  const ownersByPlayer = await loadPlayerOwners();
  const { rows: players } = await pool.query(
    `SELECT id, owner_user_id, platform_id, platform_name, player_name,
            credit, total_balance, created_at, updated_at, deleted_at
     FROM players
     ORDER BY id ASC`,
  );

  const stats = {
    assigned: 0,
    split: 0,
    cloned: 0,
    orphan: 0,
    skipped: 0,
  };

  console.log(`[migrate-players-owner] players=${players.length} dryRun=${dryRun}`);

  for (const player of players) {
    const playerId = Number(player.id);
    if (player.owner_user_id) {
      stats.skipped += 1;
      continue;
    }

    const owners = ownersByPlayer.get(playerId) || new Set();
    if (owners.size === 0) {
      stats.orphan += 1;
      console.warn(`[migrate-players-owner] orphan player ${playerId} (${player.platform_name}/${player.player_name}) — 无 profile/order 引用`);
      continue;
    }

    const orderCounts = await orderCountByUser(playerId);
    const primary = pickPrimaryOwner(owners, orderCounts);
    const others = [...owners].filter(uid => uid !== primary);

    if (dryRun) {
      console.log(
        `[dry-run] player ${playerId}: primary=${primary} others=${others.join(",") || "(none)"}`,
      );
      stats.assigned += 1;
      stats.split += others.length > 0 ? 1 : 0;
      stats.cloned += others.length;
      continue;
    }

    const client = await pool.connect();
    try {
      await client.query("BEGIN");

      await client.query(
        `UPDATE players SET owner_user_id = $2, updated_at = $3 WHERE id = $1`,
        [playerId, primary, Date.now()],
      );
      stats.assigned += 1;

      for (const otherUserId of others) {
        const newId = await clonePlayer(client, player, otherUserId);
        if (!newId)
          throw new Error(`clone player ${playerId} for ${otherUserId} failed`);

        await updateProfileAccountId(client, otherUserId, playerId, newId);
        await client.query(
          `UPDATE ${financialOrdersRelation()} SET player_id = $3 WHERE user_id = $1 AND player_id = $2`,
          [otherUserId, playerId, newId],
        );
        await client.query(
          `UPDATE money_logs SET player_id = $3 WHERE user_id = $1 AND player_id = $2`,
          [otherUserId, playerId, newId],
        );
        stats.cloned += 1;
        console.log(`[migrate-players-owner] split player ${playerId} → ${newId} for user ${otherUserId}`);
      }

      if (others.length > 0)
        stats.split += 1;

      await client.query("COMMIT");
    }
    catch (err) {
      await client.query("ROLLBACK");
      throw err;
    }
    finally {
      client.release();
    }
  }

  const { rows: missing } = await pool.query(
    `SELECT COUNT(*)::int AS cnt FROM players WHERE deleted_at IS NULL AND owner_user_id IS NULL`,
  );
  const activeMissing = Number(missing[0]?.cnt) || 0;
  console.log("[migrate-players-owner] done:", stats);
  console.log(`[migrate-players-owner] active players without owner_user_id: ${activeMissing}`);
  if (activeMissing > 0) {
    console.warn("[migrate-players-owner] 仍有未归属的活跃 player，请人工处理后再部署新代码");
  }
}

main().catch((err) => {
  console.error("[migrate-players-owner] failed:", err.message);
  process.exit(1);
});

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 一次性：把 Polymarket 卖单 money 累加到对应买单，卖单 money 置 0。
 *
 * 决策：盈亏记买单；卖单只保留回款（bet_money）。日归因仍按买单 create_at。
 *
 *   node scripts/ops/migrations/migrate-pm-sell-pnl-to-buy.mjs --dry-run
 *   node scripts/ops/migrations/migrate-pm-sell-pnl-to-buy.mjs --user gb12 --dry-run
 *   node scripts/ops/migrations/migrate-pm-sell-pnl-to-buy.mjs --execute
 *   node scripts/ops/migrations/migrate-pm-sell-pnl-to-buy.mjs --user gb12 --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

function parseArgs(argv) {
  const out = {
    dryRun: true,
    userName: "",
    help: false,
  };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function isPolymarket(provider) {
  return String(provider ?? "").trim().toLowerCase() === "polymarket";
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function sideOf(row) {
  return String(rawObj(row).pmSide ?? "").trim().toLowerCase();
}

function buyIdOf(row) {
  return String(rawObj(row).pmBuyOrderId ?? "").trim().toLowerCase();
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/migrations/migrate-pm-sell-pnl-to-buy.mjs [--dry-run|--execute] [--user NAME]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();

  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  let userIds = null;
  if (args.userName) {
    const profiles = await fetchProfiles();
    const want = args.userName.toLowerCase();
    userIds = profiles
      .filter(p => String(p.user_name ?? p.userName ?? "").toLowerCase() === want)
      .map(p => String(p.id ?? p.user_id ?? ""));
    if (!userIds.length) {
      console.error(`user not found: ${args.userName}`);
      process.exit(1);
    }
  }

  const sql = `
    SELECT order_id, user_id, player_id, provider, money, bet_money, create_at, raw
    FROM ${financialOrdersRelation()}
    WHERE LOWER(TRIM(provider)) = 'polymarket'
      ${userIds ? "AND user_id = ANY($1::text[])" : ""}
    ORDER BY create_at ASC
  `;
  const { rows } = userIds
    ? await pool.query(sql, [userIds])
    : await pool.query(sql);

  const byId = new Map();
  for (const r of rows)
    byId.set(String(r.order_id).trim().toLowerCase(), r);

  /** buyId -> { addMoney, sellIds: [] } */
  const buyAcc = new Map();
  const orphans = [];
  const sellZero = [];

  for (const sell of rows) {
    if (sideOf(sell) !== "sell")
      continue;
    const sellMoney = Number(sell.money) || 0;
    if (sellMoney === 0)
      continue;

    const buyId = buyIdOf(sell);
    if (!buyId || !byId.has(buyId)) {
      orphans.push({
        sellId: sell.order_id,
        buyId: buyId || null,
        money: sellMoney,
        userId: sell.user_id,
        playerId: sell.player_id,
      });
      continue;
    }

    const cur = buyAcc.get(buyId) || { addMoney: 0, sellIds: [] };
    cur.addMoney += sellMoney;
    cur.sellIds.push(String(sell.order_id));
    buyAcc.set(buyId, cur);
    sellZero.push(sell);
  }

  const report = {
    mode: args.dryRun ? "dry-run" : "execute",
    userFilter: args.userName || null,
    sellRowsToZero: sellZero.length,
    buysToUpdate: buyAcc.size,
    orphanSells: orphans.length,
    sampleBuys: [],
    orphans: orphans.slice(0, 30),
  };

  for (const [buyId, acc] of [...buyAcc.entries()].slice(0, 20)) {
    const buy = byId.get(buyId);
    report.sampleBuys.push({
      buyId: buy?.order_id ?? buyId,
      prevMoney: Number(buy?.money) || 0,
      addMoney: acc.addMoney,
      nextMoney: (Number(buy?.money) || 0) + acc.addMoney,
      sellCount: acc.sellIds.length,
      betMoney: Number(buy?.bet_money) || 0,
    });
  }

  console.log(JSON.stringify(report, null, 2));

  if (args.dryRun) {
    console.log("\n[dry-run] no writes. Re-run with --execute to apply.");
    process.exit(0);
  }

  const client = await pool.connect();

  let updatedBuys = 0;
  let updatedSells = 0;
  try {
    await client.query("BEGIN");

    for (const [buyId, acc] of buyAcc) {
      const buy = byId.get(buyId);
      if (!buy)
        continue;
      const prevMoney = Number(buy.money) || 0;
      const nextMoney = prevMoney + acc.addMoney;
      const raw = rawObj(buy);
      raw.money = nextMoney;
      await client.query(
        `UPDATE ${financialOrdersRelation()} SET money = $2, raw = $3::jsonb WHERE order_id = $1`,
        [buy.order_id, nextMoney, JSON.stringify(raw)],
      );
      updatedBuys += 1;
    }

    for (const sell of sellZero) {
      const raw = rawObj(sell);
      const sellMoneyCny = Number(sell.money) || 0;
      if (sellMoneyCny !== 0) {
        raw.pmRealizedPnlMigratedFromSellMoneyCny = sellMoneyCny;
        if (raw.pmRealizedPnlUsdc == null)
          raw.pmRealizedPnlUsdc = 0;
      }
      raw.money = 0;
      await client.query(
        `UPDATE ${financialOrdersRelation()} SET money = 0, raw = $2::jsonb WHERE order_id = $1`,
        [sell.order_id, JSON.stringify(raw)],
      );
      updatedSells += 1;
    }

    await client.query("COMMIT");
  }
  catch (err) {
    await client.query("ROLLBACK");
    throw err;
  }
  finally {
    client.release();
  }

  console.log(JSON.stringify({
    applied: true,
    updatedBuys,
    updatedSells,
    orphanSells: orphans.length,
  }, null, 2));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * 将早期 Polymarket match-scoped 队伍 ID 迁移为稳定队伍 ID。
 *
 * 旧 ID 形如：<sourceMatchId>:home:<teamName> / <sourceMatchId>:away:<teamName>
 * 新 ID 形如：<gameCode>:<normalizedTeamName>
 *
 * 默认 dry-run：
 *   cd changmen/server/backend && node scripts/migrate-polymarket-team-ids.mjs
 * 执行写入：
 *   cd changmen/server/backend && node scripts/migrate-polymarket-team-ids.mjs --execute
 */

import {
  getPgPool,
  initDatabaseUrl,
} from "@changmen/db";

const execute = process.argv.includes("--execute");

function normalizePolymarketTeamName(name) {
  const normalized = String(name || "")
    .normalize("NFKC")
    .trim()
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9\u4E00-\u9FFF]+/gi, "-")
    .replace(/^-+|-+$/g, "");
  return normalized || "unknown";
}

function stablePolymarketTeamId(game, name) {
  const code = String(game || "").trim();
  if (!code)
    return "";
  return `${code}:${normalizePolymarketTeamName(name)}`;
}

function parseLegacyPolymarketTeamId(venueId) {
  const text = String(venueId || "");
  const m = /^([^:]+):(home|away):(.+)$/.exec(text);
  if (!m)
    return null;
  return { sourceMatchId: m[1], side: m[2], name: m[3] };
}

await initDatabaseUrl();
const pool = getPgPool();
if (!pool) {
  console.error("[polymarket-team-ids] 无 DATABASE_URL / PG pool");
  process.exit(2);
}

try {
  const { rows } = await pool.query(
    `SELECT gb_team_id, venue, venue_team_id, venue_name, game, source, confidence
     FROM team_venue_maps
     WHERE venue = 'Polymarket'
     ORDER BY id`,
  );

  const toWriteByKey = new Map();
  const skipped = [];
  for (const row of rows) {
    const legacy = parseLegacyPolymarketTeamId(row.venue_team_id);
    if (!legacy)
      continue;
    const nextId = stablePolymarketTeamId(row.game, row.venue_name || legacy.name);
    if (!nextId) {
      skipped.push({ venue_team_id: row.venue_team_id, reason: "missing_game" });
      continue;
    }
    if (nextId === row.venue_team_id)
      continue;
    const key = `Polymarket:${nextId}`;
    if (!toWriteByKey.has(key) || row.gb_team_id != null) {
      toWriteByKey.set(key, {
        gb_team_id: row.gb_team_id ?? null,
        legacy_venue_team_id: row.venue_team_id,
        venue: "Polymarket",
        venue_team_id: nextId,
        venue_name: row.venue_name || legacy.name,
        game: row.game,
        source: row.source || "migrate",
        confidence: row.confidence ?? 1.0,
      });
    }
  }

  const toWrite = [...toWriteByKey.values()];
  console.log("[polymarket-team-ids] legacy rows:", rows.filter(r => parseLegacyPolymarketTeamId(r.venue_team_id)).length);
  console.log("[polymarket-team-ids] new rows:", toWrite.length);
  if (skipped.length)
    console.log("[polymarket-team-ids] skipped:", JSON.stringify(skipped, null, 2));
  if (!toWrite.length) {
    console.log("[polymarket-team-ids] 无需迁移");
    process.exit(0);
  }
  console.log("[polymarket-team-ids] sample:", JSON.stringify(toWrite.slice(0, 10), null, 2));
  if (!execute) {
    console.log("[polymarket-team-ids] dry-run：加 --execute 才会写入 RDS");
    process.exit(0);
  }

  for (const row of toWrite) {
    await pool.query("BEGIN");
    try {
      if (row.gb_team_id != null) {
        await pool.query(
          `UPDATE team_venue_maps
           SET gb_team_id = NULL, source = 'legacy-polymarket-team-id'
           WHERE gb_team_id = $1
             AND venue = $2
             AND venue_name = $3
             AND venue_team_id <> $4`,
          [row.gb_team_id, row.venue, row.venue_name, row.venue_team_id],
        );
      }
      await pool.query(
        `INSERT INTO team_venue_maps (gb_team_id, venue, venue_team_id, venue_name, game, source, confidence)
         VALUES ($1, $2, $3, $4, $5, $6, $7)
         ON CONFLICT (venue, venue_team_id) DO UPDATE SET
           gb_team_id = COALESCE(team_venue_maps.gb_team_id, EXCLUDED.gb_team_id),
           venue_name = EXCLUDED.venue_name,
           game = EXCLUDED.game,
           source = EXCLUDED.source,
           confidence = EXCLUDED.confidence`,
        [
          row.gb_team_id,
          row.venue,
          row.venue_team_id,
          row.venue_name,
          row.game,
          row.source || "migrate",
          row.confidence ?? 1.0,
        ],
      );
      await pool.query("COMMIT");
    }
    catch (err) {
      await pool.query("ROLLBACK");
      throw err;
    }
  }
  console.log(`[polymarket-team-ids] 写入完成：${toWrite.length} 条`);
}
catch (err) {
  console.error("[polymarket-team-ids] 失败:", err.message);
  process.exit(1);
}
finally {
  await pool.end();
}

import { financialOrdersRelation } from "@changmen/db";
import fs from "node:fs";
import path from "node:path";
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";
import { resolveGtcFinancialOrder } from "../../../../db/rds/orderModes/gtc/pm_gtc_financial.js";
import { syncPmGtcSettledOrderFinancials } from "../../../../db/rds/orderModes/gtc/pm_gtc_settlement.js";

// [changmen 扩展] 默认只读；显式指定 owner 后才允许修复其 GTC 原单财务镜像。
const args=process.argv.slice(2);
const owner=args[args.indexOf("--owner")+1];
const apply=args.includes("--apply");
if (!args.includes("--owner") || !/^[0-9a-f-]{36}$/i.test(owner??""))
  throw new Error("Usage: node repair-pm-gtc-settlement.mjs --owner UUID [--apply]");
loadChangmenEnv();
process.env.DATABASE_RDS_TARGET??="public";
process.env.DATABASE_APPLICATION_NAME="repair-pm-gtc-settlement";
const { ensurePgPoolReady }=await import("@changmen/db");
const pool=await ensurePgPoolReady();
if(!pool)throw new Error("Database unavailable");
const client=await pool.connect();
const fx=getExchange(Currency.USDT);
const round4=n=>Math.round(n*10000)/10000;
const outputDir=path.resolve("output"); fs.mkdirSync(outputDir,{recursive:true});
const stamp=new Date().toISOString().replace(/[:.]/g,"-");
try {
  await client.query(apply?"BEGIN":"BEGIN READ ONLY");
  await client.query("SET LOCAL statement_timeout='20s'");
  const records=(await client.query("SELECT id,record FROM pm_gtc_executions WHERE owner=$1 ORDER BY id"+(apply?" FOR UPDATE":""),[owner])).rows;
  const rows=(await client.query(`SELECT o.* FROM ${financialOrdersRelation("o")} WHERE o.user_id=$1 AND o.provider='Polymarket'
    AND lower(coalesce(o.raw->>'pmSide','buy'))<>'sell'
    AND (o.raw->>'pmGtcExecutionId' IS NOT NULL OR EXISTS(
      SELECT 1 FROM pm_gtc_executions e WHERE e.owner=$1
      AND (e.record->'plan'->>'playerId')::bigint=o.player_id
      AND lower(o.order_id) IN (lower(e.record->>'orderId'),lower(e.record->'plan'->>'orderHash'))))
    ORDER BY o.id`+(apply?" FOR UPDATE OF o":""),[owner])).rows;
  const findings=[];
  for(const row of rows) {
    const raw=row.raw??{};
    const record=records.find(e=>Number(e.record.plan.playerId)===Number(row.player_id)
      && [e.record.orderId,e.record.plan.orderHash].some(id=>id&&id.toLowerCase()===row.order_id.toLowerCase())
      && (!raw.pmGtcExecutionId||raw.pmGtcExecutionId===e.id));
    const financial=record?resolveGtcFinancialOrder(record.record):undefined;
    const hasSale=Number(raw.pmAttributedSellShares)>0.0001 || ["partial","closed"].includes(String(raw.pmSellState).toLowerCase())
      || Number(raw.pmSellProceeds)>0 || Math.abs(Number(raw.pmRealizedPnlUsdc)||0)>0.0001;
    if(!financial||hasSale) {
      findings.push({id:row.id,orderId:row.order_id,skipped:hasSale?"selling ledger requires sale evidence":"no validated execution financials"});
      continue;
    }
    const status=String(row.status).toLowerCase();
    const expectedMoney=status==="win"?round4(financial.pmShares*fx-financial.betMoney)
      :["lose","lost"].includes(status)?round4(-financial.betMoney):Number(row.money);
    const expectedReward=status==="win"?round4(financial.pmShares*fx):0;
    const diff=Math.abs(Number(row.bet_money)-financial.betMoney)>0.000001
      || Math.abs((Number(raw.pmStakeUsdc)||0)-financial.pmStakeUsdc)>0.000001
      || Math.abs(Number(row.money)-expectedMoney)>0.000001
      || Math.abs((Number(raw.money)||0)-expectedMoney)>0.000001
      || (["win","lose","lost"].includes(status) && Math.abs((Number(raw.reward)||0)-expectedReward)>0.000001);
    findings.push({id:row.id,orderId:row.order_id,link:row.link,executionId:record.id,status:row.status,
      beforeCost:Number(row.bet_money),expectedCost:financial.betMoney,beforeMoney:Number(row.money),expectedMoney,needsRepair:diff});
  }
  const candidates=findings.filter(f=>f.needsRepair);
  if(apply&&candidates.length) {
    // Durable local rollback evidence is written before any order changes.
    fs.writeFileSync(path.join(outputDir,`gtc-financial-backup-${stamp}.json`),JSON.stringify({owner,rows:rows.filter(r=>candidates.some(c=>c.id===r.id))},null,2),{flag:"wx"});
    for(const f of candidates) {
      const e=records.find(r=>r.id===f.executionId); const financial=resolveGtcFinancialOrder(e.record);
      await client.query(`UPDATE ${financialOrdersRelation()} SET bet_money=$3,
        raw=raw||jsonb_build_object('pmGtcExecutionId',$4::text,'betMoney',$3::float8,'pmStakeUsdc',$5::float8,
          'pmGtcBuyCost',$5::float8,'pmGtcBuyShares',$6::float8,'pmShares',$6::float8,'pmFeeUsdc',$7::float8)
        WHERE id=$1 AND user_id=$2`,[f.id,owner,financial.betMoney,e.id,financial.pmStakeUsdc,financial.pmShares,financial.pmFeeUsdc]);
      await syncPmGtcSettledOrderFinancials(client,owner,e.record.plan.playerId,f.orderId,e.id);
      const actual=(await client.query(`SELECT bet_money,money,raw->>'money' AS raw_money FROM ${financialOrdersRelation()} WHERE id=$1 AND user_id=$2`,[f.id,owner])).rows[0];
      if(Math.abs(Number(actual.money)-f.expectedMoney)>0.000001||Math.abs(Number(actual.raw_money)-f.expectedMoney)>0.000001)
        throw new Error(`Financial verification failed for ${f.orderId}`);
    }
  }
  await client.query(apply?"COMMIT":"ROLLBACK");
  const result={owner,apply,checkedAt:new Date().toISOString(),executions:records.length,ordersChecked:rows.length,
    mismatches:candidates.length,repaired:apply?candidates.length:0,findings};
  const report=path.join(outputDir,`gtc-financial-${apply?"repair":"audit"}-${stamp}.json`);
  fs.writeFileSync(report,JSON.stringify(result,null,2));
  console.log(JSON.stringify({...result,report},null,2));
} catch(error) {await client.query("ROLLBACK");throw error;}
finally {client.release();await pool.end();}

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 修复：closed 买单 money=0，但关联卖单 raw.pmRealizedPnlUsdc 非 0。
 *   node scripts/ops/migrations/restore-pm-buy-money-from-sell-pnl.mjs --dry-run
 *   node scripts/ops/migrations/restore-pm-buy-money-from-sell-pnl.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();
const { initDatabaseUrl, getPgPool } = await import("@changmen/db");

const dryRun = !process.argv.includes("--execute");
initDatabaseUrl();
const pool = getPgPool();


const { rows } = await pool.query(`
  SELECT b.order_id AS buy_id, b.money AS buy_money, b.raw AS buy_raw,
         s.order_id AS sell_id, s.raw AS sell_raw
  FROM ${financialOrdersRelation("b")}
  JOIN ${financialOrdersRelation("s")}
    ON LOWER(s.raw->>'pmBuyOrderId') = LOWER(b.order_id)
   AND s.raw->>'pmSide' = 'sell'
   AND LOWER(TRIM(s.provider)) = 'polymarket'
  WHERE LOWER(TRIM(b.provider)) = 'polymarket'
    AND b.raw->>'pmSide' = 'buy'
    AND COALESCE(b.raw->>'pmSellState', '') IN ('closed', 'partial')
    AND ABS(COALESCE(b.money, 0)) <= 0.01
    AND ABS(COALESCE(NULLIF(s.raw->>'pmRealizedPnlUsdc', ''), '0')::float) > 1e-9
`);

const fx = getExchange(Currency.USDT);
const plan = [];
for (const r of rows) {
  const pnlUsdc = Number(r.sell_raw?.pmRealizedPnlUsdc) || 0;
  const moneyCny = Math.round(pnlUsdc * fx);
  if (moneyCny === 0)
    continue;
  plan.push({
    buyId: r.buy_id,
    sellId: r.sell_id,
    pnlUsdc,
    restoreMoney: moneyCny,
  });
}

console.log(JSON.stringify({ mode: dryRun ? "dry-run" : "execute", count: plan.length, plan }, null, 2));
if (dryRun) {
  console.log("[dry-run] no writes");
  process.exit(0);
}

const client = await pool.connect();

try {
  await client.query("BEGIN");
  for (const item of plan) {
    const { rows: buys } = await client.query(
      `SELECT order_id, money, raw FROM ${financialOrdersRelation()} WHERE order_id = $1 FOR UPDATE`,
      [item.buyId],
    );
    const buy = buys[0];
    if (!buy)
      continue;
    const raw = buy.raw && typeof buy.raw === "object" ? { ...buy.raw } : {};
    raw.money = item.restoreMoney;
    raw.pmBuyMoneyRestoredFromSellPnlUsdc = item.pnlUsdc;
    await client.query(
      `UPDATE ${financialOrdersRelation()} SET money = $2, raw = $3::jsonb WHERE order_id = $1`,
      [item.buyId, item.restoreMoney, JSON.stringify(raw)],
    );
  }
  await client.query("COMMIT");
  console.log(JSON.stringify({ applied: true, updated: plan.length }, null, 2));
}
catch (err) {
  await client.query("ROLLBACK");
  throw err;
}
finally {
  client.release();
}

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 恢复被 sync 清零的 PM 卖单 money（从 raw.pmRealizedPnlUsdc × 汇率还原 CNY）。
 *
 *   node scripts/ops/migrations/restore-pm-sell-money-from-pnl-usdc.mjs --dry-run
 *   node scripts/ops/migrations/restore-pm-sell-money-from-pnl-usdc.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool } = await import("@changmen/db");

function parseArgs(argv) {
  const out = { dryRun: true, help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function pnlUsdcToMoneyCny(pnlUsdc) {
  // 对齐手动卖出：Math.round(usdc * FX)
  return Math.round((Number(pnlUsdc) || 0) * getExchange(Currency.USDT));
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log("Usage: restore-pm-sell-money-from-pnl-usdc.mjs [--dry-run|--execute]");
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();

  if (!pool) {
    console.error("No pool");
    process.exit(1);
  }

  const { rows: sells } = await pool.query(`
    SELECT s.order_id, s.money, s.raw,
           b.order_id AS buy_id, b.money AS buy_money
    FROM ${financialOrdersRelation("s")}
    LEFT JOIN ${financialOrdersRelation("b")}
      ON LOWER(b.order_id) = LOWER(COALESCE(s.raw->>'pmBuyOrderId', ''))
     AND LOWER(TRIM(b.provider)) = 'polymarket'
    WHERE LOWER(TRIM(s.provider)) = 'polymarket'
      AND s.raw->>'pmSide' = 'sell'
      AND ABS(COALESCE(s.money, 0)) <= 0.01
      AND COALESCE(s.raw->>'pmBuyOrderId', '') <> ''
      AND ABS(COALESCE(NULLIF(s.raw->>'pmRealizedPnlUsdc', ''), '0')::float) > 1e-9
      AND ABS(COALESCE(b.money, 0)) <= 0.01
  `);

  const plan = [];
  for (const s of sells) {
    const raw = rawObj(s);
    const pnlUsdc = Number(raw.pmRealizedPnlUsdc) || 0;
    const moneyCny = pnlUsdcToMoneyCny(pnlUsdc);
    if (moneyCny === 0)
      continue;
    plan.push({
      sellId: s.order_id,
      buyId: s.buy_id,
      pnlUsdc,
      restoreMoney: moneyCny,
    });
  }

  console.log(JSON.stringify({
    mode: args.dryRun ? "dry-run" : "execute",
    restoreCount: plan.length,
    sample: plan.slice(0, 15),
  }, null, 2));

  if (args.dryRun) {
    console.log("\n[dry-run] no writes");
    process.exit(0);
  }

  const client = await pool.connect();

  let n = 0;
  try {
    await client.query("BEGIN");
    for (const item of plan) {
      const { rows } = await client.query(
        `SELECT order_id, money, raw FROM ${financialOrdersRelation()} WHERE order_id = $1 FOR UPDATE`,
        [item.sellId],
      );
      const row = rows[0];
      if (!row)
        continue;
      const raw = rawObj(row);
      raw.money = item.restoreMoney;
      raw.pmSellMoneyRestoredFromPnlUsdc = item.pnlUsdc;
      await client.query(
        `UPDATE ${financialOrdersRelation()} SET money = $2, raw = $3::jsonb WHERE order_id = $1`,
        [item.sellId, item.restoreMoney, JSON.stringify(raw)],
      );
      n += 1;
    }
    await client.query("COMMIT");
  }
  catch (err) {
    await client.query("ROLLBACK");
    throw err;
  }
  finally {
    client.release();
  }

  console.log(JSON.stringify({ applied: true, updated: n }, null, 2));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { financialOrdersRelation } from "@changmen/db";
/**
 * 验证未绑单占位 Link：新单 link = RDS 入库时刻；legacy 可能 link=create_at 或 hash。
 * 用法：cd changmen/server/backend && node scripts/verify-order-link-placeholder.mjs
 */
import { getPgPool } from "@changmen/db";
import {
  ARB_LINK_MIN,
  isCreateAtPlaceholderLink,
  isHashLink,
  isInsertTimePlaceholderLink,
} from "@changmen/db";

const pool = getPgPool();
if (!pool) {
  console.error("无 DATABASE_URL / PG pool，跳过 RDS 校验");
  process.exit(2);
}

const days = Number(process.argv[2]) || 7;
const since = Date.now() - days * 24 * 60 * 60 * 1000;

const { rows } = await pool.query(
  `SELECT order_id, provider, link, create_at, user_id
   FROM ${financialOrdersRelation()}
   WHERE create_at >= $1
   ORDER BY create_at DESC
   LIMIT 500`,
  [since],
);

let createAtMatch = 0;
let insertTimePlaceholder = 0;
let hashPlaceholder = 0;
let arbBind = 0;
let other = 0;
const samples = { createAtMatch: [], insertTime: [], hash: [], arb: [] };

for (const r of rows) {
  const link = Number(r.link);
  const ca = Number(r.create_at);
  if (isCreateAtPlaceholderLink(link, ca)) {
    createAtMatch += 1;
    if (samples.createAtMatch.length < 3)
      samples.createAtMatch.push(r);
  }
  else if (isInsertTimePlaceholderLink(link, ca)) {
    insertTimePlaceholder += 1;
    if (samples.insertTime.length < 3)
      samples.insertTime.push(r);
  }
  else if (isHashLink(link)) {
    hashPlaceholder += 1;
    if (samples.hash.length < 3)
      samples.hash.push(r);
  }
  else if (link >= ARB_LINK_MIN) {
    arbBind += 1;
    if (samples.arb.length < 3)
      samples.arb.push(r);
  }
  else {
    other += 1;
  }
}

console.log(`--- orders since ${days}d (max 500 rows) ---`);
console.log({
  total: rows.length,
  legacy_create_at_placeholder: createAtMatch,
  insert_time_placeholder: insertTimePlaceholder,
  hash_placeholder: hashPlaceholder,
  arb_bind: arbBind,
  other,
});

if (samples.createAtMatch.length) {
  console.log("--- sample legacy create_at placeholder ---");
  for (const r of samples.createAtMatch) {
    console.log({
      order_id: String(r.order_id).slice(0, 24),
      provider: r.provider,
      link: String(r.link),
      create_at: String(r.create_at),
    });
  }
}

if (samples.insertTime.length) {
  console.log("--- sample insert-time placeholder ---");
  for (const r of samples.insertTime) {
    console.log({
      order_id: String(r.order_id).slice(0, 24),
      provider: r.provider,
      link: String(r.link),
      create_at: String(r.create_at),
      delta_ms: Number(r.link) - Number(r.create_at),
    });
  }
}

if (samples.hash.length) {
  console.log("--- sample legacy hash placeholder ---");
  for (const r of samples.hash) {
    console.log({
      order_id: String(r.order_id).slice(0, 24),
      provider: r.provider,
      link: r.link,
      create_at: r.create_at,
    });
  }
}

await pool.end();
process.exit(0);
